INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-13', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 13', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 13);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 1, 'throw', 'ném; vứt', 'verb', '[{"en":"Can you throw the ball to me, please?","vi":"Bạn ném quả bóng cho tôi được không?"},{"en":"Don''t throw away your old clothes; give them to charity instead.","vi":"Đừng vứt quần áo cũ đi; thay vào đó hãy đem cho từ thiện."},{"en":"He threw his bag on the bed and lay down.","vi":"Anh ấy quăng cái túi lên giường rồi nằm xuống."}]', '[{"phrase":"throw a ball"},{"phrase":"throw away"},{"phrase":"throw a party"}]', 'throw – threw – thrown', '/θrəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thr/throw/throw__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 2, 'task', 'nhiệm vụ; công việc', 'noun', '[{"en":"My first task this morning is to answer all my emails.","vi":"Việc đầu tiên của tôi sáng nay là trả lời hết email."},{"en":"Cleaning the kitchen after a big party is not an easy task.","vi":"Dọn dẹp nhà bếp sau một bữa tiệc lớn không phải là việc dễ dàng."},{"en":"The teacher gave each group a different task.","vi":"Giáo viên giao cho mỗi nhóm một nhiệm vụ khác nhau."}]', '[{"phrase":"easy task"},{"phrase":"difficult task"},{"phrase":"complete a task"}]', NULL, '/tæsk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tas/task_/task__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 3, 'normal', 'bình thường', 'adjective', '[{"en":"It''s normal to feel nervous before an important exam.","vi":"Cảm thấy lo lắng trước một kỳ thi quan trọng là chuyện bình thường."},{"en":"The train is running later than normal today.","vi":"Hôm nay tàu chạy trễ hơn bình thường."},{"en":"Her blood pressure is normal, so there''s nothing to worry about.","vi":"Huyết áp của cô ấy bình thường nên không có gì phải lo."}]', '[{"phrase":"perfectly normal"},{"phrase":"normal life"},{"phrase":"back to normal"}]', NULL, '/ˈnɔːrml/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/norma/normal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 4, 'goal', 'mục tiêu; bàn thắng', 'noun', '[{"en":"My goal is to speak English fluently by next year.","vi":"Mục tiêu của tôi là nói tiếng Anh trôi chảy vào năm sau."},{"en":"Setting small goals can help you stay motivated.","vi":"Đặt ra những mục tiêu nhỏ có thể giúp bạn giữ được động lực."},{"en":"He scored the winning goal in the last minute.","vi":"Anh ấy ghi bàn thắng quyết định ở phút cuối."}]', '[{"phrase":"set a goal"},{"phrase":"achieve a goal"},{"phrase":"score a goal"},{"phrase":"main goal"}]', NULL, '/ɡəʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/goa/goal_/goal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 5, 'associate', 'liên tưởng; liên quan đến', 'verb', '[{"en":"I always associate the smell of rain with my childhood.","vi":"Tôi luôn liên tưởng mùi mưa với tuổi thơ của mình."},{"en":"Many people associate summer with long vacations at the beach.","vi":"Nhiều người liên tưởng mùa hè với những kỳ nghỉ dài ở biển."},{"en":"Eating too much sugar is associated with many health problems.","vi":"Ăn quá nhiều đường có liên quan đến nhiều vấn đề sức khỏe."}]', '[{"phrase":"associate with"},{"phrase":"be associated with"},{"phrase":"closely associated"}]', 'associate A with B: liên tưởng A với B', '/əˈsəʊsieɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assoc/associate__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 6, 'blue', 'xanh dương; buồn', 'adjective', '[{"en":"She was wearing a blue dress at the party.","vi":"Cô ấy mặc một chiếc váy màu xanh dương tại bữa tiệc."},{"en":"The sky was clear and blue all afternoon.","vi":"Bầu trời trong xanh suốt cả buổi chiều."},{"en":"I''ve been feeling a bit blue since my best friend moved away.","vi":"Tôi cảm thấy hơi buồn từ khi bạn thân chuyển đi."}]', '[{"phrase":"dark blue"},{"phrase":"light blue"},{"phrase":"blue sky"},{"phrase":"feel blue"}]', '''xanh'' có thể là blue (xanh dương) hoặc green (xanh lá)', '/bluː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/blu/blue_/blue__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 7, 'positive', 'tích cực; chắc chắn', 'adjective', '[{"en":"Try to stay positive, even when things are difficult.","vi":"Hãy cố gắng giữ thái độ tích cực, kể cả khi mọi việc khó khăn."},{"en":"The new manager has had a positive effect on the team.","vi":"Người quản lý mới đã có ảnh hưởng tích cực đến cả nhóm."},{"en":"Are you positive that you locked the front door?","vi":"Bạn có chắc chắn là đã khóa cửa trước không?"}]', '[{"phrase":"stay positive"},{"phrase":"positive effect"},{"phrase":"positive attitude"},{"phrase":"positive feedback"}]', NULL, '/ˈpɑːzətɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/posit/positive__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 8, 'option', 'lựa chọn', 'noun', '[{"en":"Taking a taxi is probably the best option tonight.","vi":"Đi taxi có lẽ là lựa chọn tốt nhất tối nay."},{"en":"We have two options: stay home or go out for dinner.","vi":"Chúng ta có hai lựa chọn: ở nhà hoặc ra ngoài ăn tối."},{"en":"The restaurant offers several vegetarian options on its menu.","vi":"Nhà hàng có một số lựa chọn món chay trong thực đơn."}]', '[{"phrase":"the best option"},{"phrase":"have no option"},{"phrase":"a good option"}]', NULL, '/ˈɑːpʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opt/optio/option__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 9, 'box', 'hộp; thùng; ô', 'noun', '[{"en":"She keeps all her old photos in a shoe box.","vi":"Cô ấy cất tất cả ảnh cũ trong một hộp giày."},{"en":"We packed our books into boxes before moving.","vi":"Chúng tôi đóng sách vào thùng trước khi chuyển nhà."},{"en":"Please check the box if you agree to the terms.","vi":"Vui lòng đánh dấu vào ô nếu bạn đồng ý với các điều khoản."}]', '[{"phrase":"cardboard box"},{"phrase":"shoe box"},{"phrase":"check the box"},{"phrase":"a box of chocolates"}]', NULL, '/bɑːks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/box/box__/box__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 10, 'huge', 'rất lớn; khổng lồ', 'adjective', '[{"en":"They live in a huge house near the lake.","vi":"Họ sống trong một ngôi nhà rất lớn gần hồ."},{"en":"Winning the scholarship was a huge surprise for her.","vi":"Giành được học bổng là một bất ngờ rất lớn đối với cô ấy."},{"en":"The school concert was a huge success this year.","vi":"Buổi hòa nhạc của trường năm nay đã thành công lớn."}]', '[{"phrase":"huge success"},{"phrase":"huge amount"},{"phrase":"huge difference"}]', NULL, '/hjuːdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hug/huge_/huge__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 11, 'message', 'tin nhắn; lời nhắn; thông điệp', 'noun', '[{"en":"I''ll send you a message when I get home.","vi":"Tôi sẽ gửi tin nhắn cho bạn khi về đến nhà."},{"en":"She''s not in right now, but can I take a message?","vi":"Cô ấy hiện không có ở đây, tôi ghi lại lời nhắn cho bạn nhé?"},{"en":"The movie has a simple message about being kind to others.","vi":"Bộ phim mang một thông điệp đơn giản về việc tử tế với người khác."}]', '[{"phrase":"send a message"},{"phrase":"leave a message"},{"phrase":"take a message"},{"phrase":"text message"}]', NULL, '/ˈmesɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mes/messa/message__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 12, 'instance', 'ví dụ; trường hợp', 'noun', '[{"en":"There are many ways to save money, for instance cooking at home.","vi":"Có nhiều cách để tiết kiệm tiền, chẳng hạn như nấu ăn ở nhà."},{"en":"In this instance, I think you should ask your manager first.","vi":"Trong trường hợp này, tôi nghĩ bạn nên hỏi quản lý trước."},{"en":"The report describes several instances of students cheating on tests.","vi":"Bản báo cáo mô tả một số trường hợp học sinh gian lận khi làm bài kiểm tra."}]', '[{"phrase":"for instance"},{"phrase":"in this instance"},{"phrase":"in some instances"}]', 'for instance = for example (chẳng hạn)', '/ˈɪnstəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insta/instance__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 13, 'style', 'phong cách; kiểu', 'noun', '[{"en":"The students really enjoy their teacher''s relaxed teaching style.","vi":"Học sinh rất thích phong cách giảng dạy thoải mái của giáo viên mình."},{"en":"The hotel was built in an old French style.","vi":"Khách sạn được xây theo phong cách Pháp cổ."},{"en":"This style of shoe is very popular with teenagers.","vi":"Kiểu giày này rất được giới trẻ ưa chuộng."}]', '[{"phrase":"teaching style"},{"phrase":"writing style"},{"phrase":"in style"}]', NULL, '/staɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sty/style/style__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 14, 'refer', 'nhắc đến; ám chỉ; tham khảo', 'verb', '[{"en":"In his speech, he referred to his years living abroad.","vi":"Trong bài phát biểu, anh ấy đã nhắc đến những năm sống ở nước ngoài."},{"en":"Who were you referring to when you said that?","vi":"Bạn đang ám chỉ ai khi nói điều đó?"},{"en":"She referred to her notes several times during her presentation.","vi":"Cô ấy đã xem ghi chú của mình vài lần trong bài thuyết trình."}]', '[{"phrase":"refer to"},{"phrase":"refer back to"},{"phrase":"be referred to as"}]', 'refer to sth · refer – referred – referred', '/rɪˈfɜːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refer/refer__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 15, 'cold', 'lạnh; lạnh lùng', 'adjective', '[{"en":"It''s really cold outside, so wear a warm coat.","vi":"Ngoài trời rất lạnh, nên hãy mặc áo khoác ấm."},{"en":"Would you like a cold drink after your long walk?","vi":"Bạn có muốn uống gì lạnh sau chuyến đi bộ dài không?"},{"en":"He gave me a cold look and walked away.","vi":"Anh ấy nhìn tôi lạnh lùng rồi bỏ đi."}]', '[{"phrase":"cold weather"},{"phrase":"cold water"},{"phrase":"cold drink"},{"phrase":"catch a cold"}]', 'Danh từ: catch a cold (bị cảm lạnh)', '/kəʊld/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/cold_/cold__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 16, 'push', 'đẩy; ấn; thúc ép', 'verb', '[{"en":"You need to push the door hard because it sometimes sticks.","vi":"Bạn cần đẩy cửa mạnh vì đôi khi nó bị kẹt."},{"en":"Push this button to turn on the machine.","vi":"Ấn nút này để bật máy."},{"en":"My parents never pushed me to study medicine.","vi":"Bố mẹ tôi chưa bao giờ ép tôi học ngành y."}]', '[{"phrase":"push the door"},{"phrase":"push a button"},{"phrase":"push hard"}]', NULL, '/pʊʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pus/push_/push__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 17, 'quarter', 'một phần tư; mười lăm phút; quý', 'noun', '[{"en":"About a quarter of the students walk to school.","vi":"Khoảng một phần tư số học sinh đi bộ đến trường."},{"en":"The meeting starts at a quarter past nine.","vi":"Cuộc họp bắt đầu lúc chín giờ mười lăm."},{"en":"The company''s sales rose sharply in the third quarter.","vi":"Doanh số của công ty đã tăng mạnh trong quý ba."}]', '[{"phrase":"a quarter of"},{"phrase":"quarter past"},{"phrase":"quarter to"},{"phrase":"third quarter"}]', NULL, '/ˈkwɔːrtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qua/quart/quarter__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 18, 'assume', 'cho rằng; giả sử', 'verb', '[{"en":"I assumed you already knew about the party.","vi":"Tôi cứ tưởng bạn đã biết về bữa tiệc rồi."},{"en":"Don''t assume that everyone agrees with you.","vi":"Đừng cho rằng mọi người đều đồng ý với bạn."},{"en":"Let''s assume the flight leaves on time and plan from there.","vi":"Hãy giả sử chuyến bay cất cánh đúng giờ và lên kế hoạch từ đó."}]', '[{"phrase":"assume that"},{"phrase":"safe to assume"},{"phrase":"wrongly assume"}]', NULL, '/əˈsuːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/assum/assume__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 19, 'baby', 'em bé', 'noun', '[{"en":"The baby is sleeping, so please be quiet.","vi":"Em bé đang ngủ, nên làm ơn giữ yên lặng."},{"en":"My sister is going to have a baby in March.","vi":"Chị gái tôi sắp sinh em bé vào tháng Ba."},{"en":"They bought some new baby clothes for their son.","vi":"Họ đã mua vài bộ quần áo em bé mới cho con trai."}]', '[{"phrase":"have a baby"},{"phrase":"newborn baby"},{"phrase":"baby clothes"},{"phrase":"baby boy"}]', NULL, '/ˈbeɪbi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bab/baby_/baby__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 20, 'successful', 'thành công; thành đạt', 'adjective', '[{"en":"Her new restaurant has been very successful.","vi":"Nhà hàng mới của cô ấy rất thành công."},{"en":"He is a successful businessman with three companies.","vi":"Anh ấy là một doanh nhân thành đạt với ba công ty."},{"en":"Were you successful in finding a new apartment?","vi":"Bạn tìm căn hộ mới có thành công không?"}]', '[{"phrase":"highly successful"},{"phrase":"successful career"},{"phrase":"successful businessman"},{"phrase":"successful in"}]', NULL, '/səkˈsesfl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/suc/succe/successful__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 21, 'sing', 'hát', 'verb', '[{"en":"She sings in the school choir every Friday.","vi":"Cô ấy hát trong dàn hợp xướng của trường vào mỗi thứ Sáu."},{"en":"My grandfather used to sing old songs to us at bedtime.","vi":"Ông tôi thường hát những bài hát cũ cho chúng tôi nghe trước giờ đi ngủ."},{"en":"Have you ever sung in front of a large audience?","vi":"Bạn đã bao giờ hát trước đông khán giả chưa?"}]', '[{"phrase":"sing a song"},{"phrase":"sing along"},{"phrase":"sing in a choir"}]', 'sing – sang – sung', '/sɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sin/sing_/sing__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 22, 'doubt', 'nghi ngờ; không tin là', 'verb', '[{"en":"I doubt that he will arrive on time.","vi":"Tôi không tin là anh ấy sẽ đến đúng giờ."},{"en":"She never doubted her decision to study abroad.","vi":"Cô ấy chưa bao giờ nghi ngờ quyết định đi du học của mình."},{"en":"Nobody doubts that she is the best player on the team.","vi":"Không ai nghi ngờ rằng cô ấy là cầu thủ giỏi nhất đội."}]', '[{"phrase":"doubt that"},{"phrase":"seriously doubt"},{"phrase":"never doubt"}]', 'Danh từ: no doubt (chắc chắn, không nghi ngờ gì)', '/daʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dou/doubt/doubt__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 23, 'competition', 'cuộc thi; sự cạnh tranh', 'noun', '[{"en":"My son won first prize in a drawing competition.","vi":"Con trai tôi đã giành giải nhất trong một cuộc thi vẽ."},{"en":"There is strong competition between the two coffee shops.","vi":"Có sự cạnh tranh gay gắt giữa hai quán cà phê."},{"en":"Are you going to enter the singing competition next month?","vi":"Bạn có định tham gia cuộc thi hát vào tháng sau không?"}]', '[{"phrase":"win a competition"},{"phrase":"enter a competition"},{"phrase":"strong competition"}]', NULL, '/ˌkɑːmpəˈtɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compe/competition__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 24, 'theory', 'lý thuyết; giả thuyết', 'noun', '[{"en":"In theory, the plan should work, but it''s still risky.","vi":"Về lý thuyết, kế hoạch này sẽ hiệu quả, nhưng nó vẫn có rủi ro."},{"en":"Students need to learn both theory and practice in this course.","vi":"Sinh viên cần học cả lý thuyết lẫn thực hành trong khóa học này."},{"en":"I have a theory about why our cat keeps running away.","vi":"Tôi có một giả thuyết về lý do con mèo nhà tôi cứ bỏ đi."}]', '[{"phrase":"in theory"},{"phrase":"theory and practice"},{"phrase":"develop a theory"}]', NULL, '/ˈθiːəri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/theor/theory__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 25, 'propose', 'đề xuất; cầu hôn', 'verb', '[{"en":"She proposed a new plan to reduce costs.","vi":"Cô ấy đã đề xuất một kế hoạch mới để giảm chi phí."},{"en":"I propose that we meet again next Monday.","vi":"Tôi đề nghị chúng ta gặp lại nhau vào thứ Hai tới."},{"en":"He proposed to his girlfriend on the beach at sunset.","vi":"Anh ấy đã cầu hôn bạn gái trên bãi biển lúc hoàng hôn."}]', '[{"phrase":"propose a plan"},{"phrase":"propose changes"},{"phrase":"propose to"}]', NULL, '/prəˈpəʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/propo/propose__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 26, 'reference', 'sự nhắc đến; sự tham khảo; thư giới thiệu', 'noun', '[{"en":"She made no reference to the problem in her email.","vi":"Cô ấy không hề nhắc đến vấn đề đó trong email."},{"en":"Please keep this guide in a safe place for future reference.","vi":"Hãy cất cuốn hướng dẫn này ở nơi an toàn để tham khảo sau này."},{"en":"My former manager agreed to write me a reference.","vi":"Quản lý cũ của tôi đã đồng ý viết thư giới thiệu cho tôi."}]', '[{"phrase":"make reference to"},{"phrase":"for future reference"},{"phrase":"reference book"},{"phrase":"letter of reference"}]', NULL, '/ˈrefrəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refer/reference__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 27, 'argument', 'cuộc cãi vã; lý lẽ', 'noun', '[{"en":"My brother and I had an argument about the TV remote.","vi":"Tôi và anh trai đã cãi nhau vì cái điều khiển tivi."},{"en":"They got into a big argument over money.","vi":"Họ đã cãi nhau to vì chuyện tiền bạc."},{"en":"She made a strong argument for learning a second language.","vi":"Cô ấy đưa ra một lý lẽ thuyết phục cho việc học ngoại ngữ thứ hai."}]', '[{"phrase":"have an argument"},{"phrase":"strong argument"},{"phrase":"argument about"},{"phrase":"argument for"}]', NULL, '/ˈɑːrɡjumənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arg/argum/argument__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 28, 'adult', 'người lớn; người trưởng thành', 'noun', '[{"en":"Children must be with an adult to enter the pool.","vi":"Trẻ em phải đi cùng người lớn mới được vào hồ bơi."},{"en":"Tickets cost ten dollars for adults and five for children.","vi":"Vé có giá mười đô la cho người lớn và năm đô cho trẻ em."},{"en":"Now that you''re an adult, you need to make your own decisions.","vi":"Giờ bạn đã là người trưởng thành, bạn cần tự đưa ra quyết định."}]', '[{"phrase":"young adult"},{"phrase":"adult life"},{"phrase":"adults and children"}]', NULL, '/əˈdʌlt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adu/adult/adult__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-13', 29, 'fly', 'bay; đi máy bay', 'verb', '[{"en":"Birds fly south when the weather gets cold.","vi":"Chim bay về phương nam khi trời trở lạnh."},{"en":"We flew to Da Nang for our summer vacation.","vi":"Chúng tôi đã bay ra Đà Nẵng trong kỳ nghỉ hè."},{"en":"Is it cheaper to fly or take the train?","vi":"Đi máy bay hay đi tàu thì rẻ hơn?"}]', '[{"phrase":"fly to"},{"phrase":"fly home"},{"phrase":"fly away"},{"phrase":"fly a kite"}]', 'fly – flew – flown', '/flaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fly/fly__/fly__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-14', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 14', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 14);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 1, 'document', 'tài liệu; văn bản; giấy tờ', 'noun', '[{"en":"Please read the document carefully before you sign it.","vi":"Vui lòng đọc kỹ tài liệu trước khi ký."},{"en":"I saved the document on my laptop last night.","vi":"Tối qua tôi đã lưu văn bản đó trong máy tính xách tay."},{"en":"You will need to bring some important documents to the bank.","vi":"Bạn sẽ cần mang theo một số giấy tờ quan trọng đến ngân hàng."}]', '[{"phrase":"sign a document"},{"phrase":"important document"},{"phrase":"legal document"},{"phrase":"official document"}]', NULL, '/ˈdɑːkjumənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/doc/docum/document__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 2, 'pattern', 'mẫu; hoa văn; quy luật', 'noun', '[{"en":"She bought a dress with a pattern of small flowers.","vi":"Cô ấy mua một chiếc váy có hoa văn những bông hoa nhỏ."},{"en":"The doctor noticed a clear pattern in his sleeping habits.","vi":"Bác sĩ nhận thấy một quy luật rõ ràng trong thói quen ngủ của anh ấy."},{"en":"Children learn to speak by hearing the same sentence patterns many times.","vi":"Trẻ em học nói bằng cách nghe những mẫu câu giống nhau nhiều lần."}]', '[{"phrase":"a clear pattern"},{"phrase":"follow a pattern"},{"phrase":"weather patterns"}]', NULL, '/ˈpætərn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pat/patte/pattern__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 3, 'application', 'đơn xin; ứng dụng', 'noun', '[{"en":"I sent my job application to the company last week.","vi":"Tuần trước tôi đã gửi đơn xin việc đến công ty đó."},{"en":"Your visa application must be completed in English.","vi":"Đơn xin thị thực của bạn phải được điền bằng tiếng Anh."},{"en":"This application helps you track how much water you drink.","vi":"Ứng dụng này giúp bạn theo dõi lượng nước mình uống."}]', '[{"phrase":"job application"},{"phrase":"application form"},{"phrase":"submit an application"},{"phrase":"mobile application"}]', NULL, '/ˌæplɪˈkeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appli/application__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 4, 'hot', 'nóng; cay', 'adjective', '[{"en":"It''s too hot to go outside this afternoon.","vi":"Chiều nay trời quá nóng để ra ngoài."},{"en":"Be careful, the soup is still very hot.","vi":"Cẩn thận nhé, súp vẫn còn rất nóng."},{"en":"This curry is too hot for my children.","vi":"Món cà ri này quá cay đối với các con tôi."}]', '[{"phrase":"hot weather"},{"phrase":"hot water"},{"phrase":"a hot day"}]', NULL, '/hɑːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hot/hot__/hot__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 5, 'obviously', 'rõ ràng; hiển nhiên', 'adverb', '[{"en":"She was obviously upset when she heard the news.","vi":"Rõ ràng cô ấy rất buồn khi nghe tin đó."},{"en":"Obviously, you should never drive after drinking alcohol.","vi":"Hiển nhiên là bạn không bao giờ nên lái xe sau khi uống rượu."},{"en":"He was obviously tired after the long flight.","vi":"Rõ ràng anh ấy đã mệt sau chuyến bay dài."}]', '[{"phrase":"obviously upset"},{"phrase":"quite obviously"},{"phrase":"obviously wrong"}]', NULL, '/ˈɑːbviəsli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obv/obvio/obviously__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 6, 'unclear', 'không rõ; chưa rõ ràng', 'adjective', '[{"en":"It is still unclear what caused the fire.","vi":"Vẫn chưa rõ nguyên nhân gây ra vụ cháy."},{"en":"The teacher''s instructions were unclear, so many students got confused.","vi":"Hướng dẫn của giáo viên không rõ ràng nên nhiều học sinh bị bối rối."},{"en":"I''m unclear about what time the meeting starts.","vi":"Tôi chưa rõ cuộc họp bắt đầu lúc mấy giờ."}]', '[{"phrase":"it is unclear"},{"phrase":"still unclear"},{"phrase":"remain unclear"}]', NULL, '/ˌʌnˈklɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unc/uncle/unclear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 7, 'bill', 'hóa đơn; tờ tiền', 'noun', '[{"en":"Excuse me, could we have the bill, please?","vi":"Xin lỗi, cho chúng tôi xin hóa đơn được không?"},{"en":"We need to pay the electricity bill before Friday.","vi":"Chúng ta cần trả hóa đơn tiền điện trước thứ Sáu."},{"en":"He paid for lunch with a twenty-dollar bill.","vi":"Anh ấy trả tiền bữa trưa bằng một tờ hai mươi đô la."}]', '[{"phrase":"pay the bill"},{"phrase":"electricity bill"},{"phrase":"phone bill"},{"phrase":"split the bill"}]', NULL, '/bɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bil/bill_/bill__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 8, 'search', 'tìm kiếm; lục soát', 'verb', '[{"en":"I searched everywhere for my keys but couldn''t find them.","vi":"Tôi đã tìm chìa khóa khắp nơi nhưng không thấy."},{"en":"You can search the internet for cheap flights.","vi":"Bạn có thể tìm vé máy bay giá rẻ trên mạng."},{"en":"Security guards searched our bags at the entrance.","vi":"Nhân viên bảo vệ đã lục soát túi của chúng tôi ở lối vào."}]', '[{"phrase":"search for"},{"phrase":"search the internet"},{"phrase":"search everywhere"}]', 'search for sth: tìm cái gì; search a place/bag: lục soát', '/sɜːrtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sea/searc/search__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 9, 'separate', 'riêng; riêng biệt; tách biệt', 'adjective', '[{"en":"When we were kids, my brother and I had separate bedrooms.","vi":"Hồi nhỏ, tôi và anh trai có phòng ngủ riêng."},{"en":"Please keep raw meat separate from other food.","vi":"Hãy để thịt sống tách biệt với các thực phẩm khác."},{"en":"Write each answer on a separate sheet of paper.","vi":"Hãy viết mỗi câu trả lời trên một tờ giấy riêng."}]', '[{"phrase":"separate room"},{"phrase":"keep separate"},{"phrase":"a separate sheet"},{"phrase":"separate from"}]', 'separate (v): tách ra, chia ra', '/ˈseprət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sep/separ/separate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 10, 'central', 'trung tâm; chính, chủ yếu', 'adjective', '[{"en":"We found a small hotel in a central location.","vi":"Chúng tôi tìm được một khách sạn nhỏ ở vị trí trung tâm."},{"en":"Family plays a central role in her life.","vi":"Gia đình giữ vai trò chính trong cuộc sống của cô ấy."},{"en":"The central station is only a ten-minute walk away.","vi":"Nhà ga trung tâm chỉ cách đây mười phút đi bộ."}]', '[{"phrase":"central role"},{"phrase":"central location"},{"phrase":"central part"}]', NULL, '/ˈsentrəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cen/centr/central__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 11, 'career', 'sự nghiệp; nghề nghiệp', 'noun', '[{"en":"She started her career as a nurse in a small hospital.","vi":"Cô ấy bắt đầu sự nghiệp là một y tá tại một bệnh viện nhỏ."},{"en":"What career do you want after you finish university?","vi":"Bạn muốn theo nghề gì sau khi học xong đại học?"},{"en":"He changed careers at forty and became a teacher.","vi":"Anh ấy đổi nghề ở tuổi bốn mươi và trở thành giáo viên."}]', '[{"phrase":"start a career"},{"phrase":"change careers"},{"phrase":"career choice"},{"phrase":"a successful career"}]', NULL, '/kəˈrɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/caree/career__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 12, 'anyway', 'dù sao; dù sao thì', 'adverb', '[{"en":"It was raining, but we went for a walk anyway.","vi":"Trời mưa nhưng dù sao chúng tôi vẫn đi dạo."},{"en":"Anyway, I should go now because it''s getting late.","vi":"Dù sao thì tôi cũng nên đi bây giờ vì đã muộn rồi."},{"en":"I didn''t really want that job anyway.","vi":"Dù sao thì tôi cũng không thực sự muốn công việc đó."}]', '[{"phrase":"thanks anyway"},{"phrase":"but anyway"}]', NULL, '/ˈeniweɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/any/anywa/anyway__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 13, 'speech', 'bài phát biểu; khả năng nói', 'noun', '[{"en":"The manager gave a short speech at the party.","vi":"Người quản lý đã có một bài phát biểu ngắn tại bữa tiệc."},{"en":"I get nervous whenever I have to make a speech.","vi":"Tôi hay lo lắng mỗi khi phải phát biểu."},{"en":"Young children develop speech at very different ages.","vi":"Trẻ nhỏ phát triển khả năng nói ở những độ tuổi rất khác nhau."}]', '[{"phrase":"give a speech"},{"phrase":"make a speech"},{"phrase":"short speech"},{"phrase":"wedding speech"}]', NULL, '/spiːtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speec/speech__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 14, 'dog', 'con chó', 'noun', '[{"en":"We take our dog for a walk every evening.","vi":"Chúng tôi dắt chó đi dạo mỗi tối."},{"en":"My neighbor''s dog barks loudly whenever someone walks past.","vi":"Con chó nhà hàng xóm sủa ầm lên mỗi khi có người đi ngang qua."},{"en":"Do you think dogs make better pets than cats?","vi":"Bạn có nghĩ chó là thú cưng tốt hơn mèo không?"}]', '[{"phrase":"walk the dog"},{"phrase":"feed the dog"},{"phrase":"dog food"}]', NULL, '/dɔːɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dog/dog__/dog__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 15, 'officer', 'sĩ quan; cảnh sát; nhân viên', 'noun', '[{"en":"A police officer helped us find the way to the station.","vi":"Một cảnh sát đã giúp chúng tôi tìm đường đến nhà ga."},{"en":"She works as a customs officer at the airport.","vi":"Cô ấy làm nhân viên hải quan tại sân bay."},{"en":"Her father was an officer in the navy for twenty years.","vi":"Bố cô ấy làm sĩ quan hải quân suốt hai mươi năm."}]', '[{"phrase":"police officer"},{"phrase":"customs officer"},{"phrase":"army officer"},{"phrase":"senior officer"}]', NULL, '/ˈɑːfɪsər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/off/offic/officer__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 16, 'throughout', 'suốt; khắp', 'preposition', '[{"en":"It rained throughout the day, so we stayed inside.","vi":"Trời mưa suốt cả ngày nên chúng tôi ở trong nhà."},{"en":"The restaurant is famous throughout the country.","vi":"Nhà hàng này nổi tiếng khắp cả nước."},{"en":"She stayed calm and smiled throughout the whole interview.","vi":"Cô ấy giữ bình tĩnh và mỉm cười suốt buổi phỏng vấn."}]', '[{"phrase":"throughout the day"},{"phrase":"throughout the year"},{"phrase":"throughout the world"},{"phrase":"throughout the country"}]', NULL, '/θruːˈaʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thr/throu/throughout__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 17, 'oil', 'dầu', 'noun', '[{"en":"Heat a little oil in the pan before adding the onions.","vi":"Đun nóng một ít dầu trong chảo trước khi cho hành vào."},{"en":"The mechanic said my car needs an oil change.","vi":"Thợ sửa xe nói xe của tôi cần thay dầu."},{"en":"Olive oil is a healthy choice for salads.","vi":"Dầu ô liu là lựa chọn tốt cho sức khỏe khi làm salad."}]', '[{"phrase":"olive oil"},{"phrase":"cooking oil"},{"phrase":"oil change"},{"phrase":"oil price"}]', 'không đếm được', '/ɔɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/oil/oil__/oil__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 18, 'dress', 'váy; váy liền', 'noun', '[{"en":"She wore a long blue dress to the wedding.","vi":"Cô ấy mặc một chiếc váy dài màu xanh dương đến dự đám cưới."},{"en":"This dress is too small, so I need a bigger size.","vi":"Chiếc váy này chật quá nên tôi cần cỡ lớn hơn."},{"en":"My daughter wants a new dress for her birthday party.","vi":"Con gái tôi muốn có một chiếc váy mới cho tiệc sinh nhật."}]', '[{"phrase":"wear a dress"},{"phrase":"wedding dress"},{"phrase":"long dress"},{"phrase":"summer dress"}]', 'dress (v): mặc quần áo; get dressed: mặc đồ', '/dres/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dre/dress/dress__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 19, 'profit', 'lợi nhuận; tiền lãi', 'noun', '[{"en":"The small shop made a good profit last year.","vi":"Năm ngoái cửa hàng nhỏ đó thu được lợi nhuận khá tốt."},{"en":"They sold the old house at a profit.","vi":"Họ đã bán căn nhà cũ và có lãi."},{"en":"Our company''s profits rose by ten percent this year.","vi":"Lợi nhuận của công ty chúng tôi tăng mười phần trăm trong năm nay."}]', '[{"phrase":"make a profit"},{"phrase":"at a profit"},{"phrase":"profit margin"}]', NULL, '/ˈprɑːfɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/profi/profit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 20, 'guess', 'đoán; nghĩ là', 'verb', '[{"en":"Can you guess how old my grandmother is?","vi":"Bạn có đoán được bà tôi bao nhiêu tuổi không?"},{"en":"I didn''t know the answer, so I just guessed.","vi":"Tôi không biết câu trả lời nên chỉ đoán thôi."},{"en":"I guess we should leave before the traffic gets bad.","vi":"Tôi nghĩ chúng ta nên đi trước khi đường bị kẹt xe."}]', '[{"phrase":"guess the answer"},{"phrase":"take a guess"},{"phrase":"I guess so"}]', NULL, '/ɡes/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gue/guess/guess__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 21, 'fun', 'niềm vui; sự vui vẻ', 'noun', '[{"en":"We had a lot of fun at the beach yesterday.","vi":"Hôm qua chúng tôi đã rất vui ở bãi biển."},{"en":"Learning a new language can be great fun.","vi":"Học một ngôn ngữ mới có thể là niềm vui lớn."},{"en":"The kids played in the snow just for fun.","vi":"Bọn trẻ chơi trong tuyết chỉ để cho vui."}]', '[{"phrase":"have fun"},{"phrase":"for fun"},{"phrase":"great fun"},{"phrase":"a lot of fun"}]', 'không đếm được; have fun: vui vẻ, chơi vui', '/fʌn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/fun__/fun__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 22, 'protect', 'bảo vệ; che chở', 'verb', '[{"en":"Wear sunglasses to protect your eyes from the sun.","vi":"Hãy đeo kính râm để bảo vệ mắt khỏi ánh nắng."},{"en":"Parents always want to protect their children.","vi":"Cha mẹ luôn muốn che chở cho con cái."},{"en":"We must do more to protect the environment.","vi":"Chúng ta phải làm nhiều hơn nữa để bảo vệ môi trường."}]', '[{"phrase":"protect from"},{"phrase":"protect the environment"},{"phrase":"protect yourself"}]', 'protect sb/sth from sth', '/prəˈtekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prote/protect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 23, 'resource', 'tài nguyên; nguồn lực; tài liệu', 'noun', '[{"en":"Water is one of our most important natural resources.","vi":"Nước là một trong những tài nguyên thiên nhiên quan trọng nhất của chúng ta."},{"en":"The school doesn''t have enough resources to buy new computers.","vi":"Trường không có đủ nguồn lực để mua máy tính mới."},{"en":"The library has many useful resources for students learning English.","vi":"Thư viện có nhiều tài liệu hữu ích cho sinh viên học tiếng Anh."}]', '[{"phrase":"natural resources"},{"phrase":"limited resources"},{"phrase":"learning resources"}]', NULL, '/ˈriːsɔːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resou/resource__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 24, 'science', 'khoa học; môn khoa học', 'noun', '[{"en":"Science was my favorite subject in high school.","vi":"Khoa học là môn học yêu thích của tôi hồi cấp ba."},{"en":"Modern science has helped people live longer.","vi":"Khoa học hiện đại đã giúp con người sống lâu hơn."},{"en":"She wants to study computer science at university.","vi":"Cô ấy muốn học ngành khoa học máy tính ở đại học."}]', '[{"phrase":"computer science"},{"phrase":"science teacher"},{"phrase":"modern science"},{"phrase":"science fiction"}]', NULL, '/ˈsaɪəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sci/scien/science__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 25, 'disease', 'bệnh; bệnh tật', 'noun', '[{"en":"Washing your hands helps stop the spread of disease.","vi":"Rửa tay giúp ngăn chặn sự lây lan của bệnh tật."},{"en":"Eating too much sugar can increase the risk of heart disease.","vi":"Ăn quá nhiều đường có thể làm tăng nguy cơ mắc bệnh tim."},{"en":"Doctors are still learning about this rare disease.","vi":"Các bác sĩ vẫn đang tìm hiểu về căn bệnh hiếm gặp này."}]', '[{"phrase":"heart disease"},{"phrase":"spread of disease"},{"phrase":"rare disease"},{"phrase":"infectious disease"}]', NULL, '/dɪˈziːz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disea/disease__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 26, 'balance', 'sự cân bằng; thăng bằng; số dư', 'noun', '[{"en":"It''s hard to find a good balance between work and family.","vi":"Thật khó tìm được sự cân bằng tốt giữa công việc và gia đình."},{"en":"He lost his balance and fell off his bike.","vi":"Anh ấy mất thăng bằng và ngã khỏi xe đạp."},{"en":"You can check your account balance on the bank''s app.","vi":"Bạn có thể kiểm tra số dư tài khoản trên ứng dụng của ngân hàng."}]', '[{"phrase":"lose your balance"},{"phrase":"keep your balance"},{"phrase":"work-life balance"},{"phrase":"account balance"}]', NULL, '/ˈbæləns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bal/balan/balance__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 27, 'damage', 'sự hư hại; thiệt hại', 'noun', '[{"en":"The storm caused serious damage to many homes.","vi":"Cơn bão gây thiệt hại nghiêm trọng cho nhiều ngôi nhà."},{"en":"Luckily, there was no damage to my car.","vi":"May mắn là xe của tôi không bị hư hại gì."},{"en":"Too much sun can do damage to your skin.","vi":"Phơi nắng quá nhiều có thể gây hại cho da của bạn."}]', '[{"phrase":"cause damage"},{"phrase":"serious damage"},{"phrase":"damage to"},{"phrase":"do damage"}]', 'không đếm được; damage (v): làm hư hại', '/ˈdæmɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dam/damag/damage__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 28, 'basis', 'cơ sở; nền tảng', 'noun', '[{"en":"Trust is the basis of every good friendship.","vi":"Sự tin tưởng là nền tảng của mọi tình bạn tốt đẹp."},{"en":"Decisions should be made on the basis of facts.","vi":"Các quyết định nên được đưa ra dựa trên cơ sở sự thật."},{"en":"These notes will form the basis of my final report.","vi":"Những ghi chú này sẽ là cơ sở cho bản báo cáo cuối cùng của tôi."}]', '[{"phrase":"on the basis of"},{"phrase":"form the basis"},{"phrase":"on a daily basis"},{"phrase":"on a regular basis"}]', 'số nhiều: bases; on a daily basis: hằng ngày', '/ˈbeɪsɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bas/basis/basis__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-14', 29, 'author', 'tác giả', 'noun', '[{"en":"Who is the author of this book?","vi":"Ai là tác giả của cuốn sách này?"},{"en":"The author spent five years writing her first novel.","vi":"Tác giả đã dành năm năm để viết cuốn tiểu thuyết đầu tay của mình."},{"en":"My favorite author is visiting our local bookstore next week.","vi":"Tác giả yêu thích của tôi sẽ đến hiệu sách gần nhà chúng tôi vào tuần tới."}]', '[{"phrase":"famous author"},{"phrase":"best-selling author"},{"phrase":"favorite author"}]', NULL, '/ˈɔːθər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aut/autho/author__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-15', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 15', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 15);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 1, 'basic', 'cơ bản; đơn giản, sơ sài', 'adjective', '[{"en":"You only need basic computer skills for this job.","vi":"Bạn chỉ cần kỹ năng máy tính cơ bản cho công việc này."},{"en":"Everyone should learn some basic first aid.","vi":"Mọi người nên học một chút sơ cứu cơ bản."},{"en":"The hotel room was quite basic, but it was clean.","vi":"Phòng khách sạn khá đơn sơ nhưng sạch sẽ."}]', '[{"phrase":"basic skills"},{"phrase":"basic knowledge"},{"phrase":"basic needs"}]', NULL, '/ˈbeɪsɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bas/basic/basic__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 2, 'encourage', 'khuyến khích; động viên', 'verb', '[{"en":"My parents always encouraged me to read books.","vi":"Bố mẹ tôi luôn khuyến khích tôi đọc sách."},{"en":"Teachers should encourage students to ask questions in class.","vi":"Giáo viên nên khuyến khích học sinh đặt câu hỏi trong lớp."},{"en":"Her friends encouraged her when she felt like giving up.","vi":"Bạn bè đã động viên cô ấy khi cô ấy muốn bỏ cuộc."}]', '[{"phrase":"strongly encourage"},{"phrase":"encourage students"},{"phrase":"feel encouraged"}]', NULL, '/ɪnˈkɜːrɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/enc/encou/encourage__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 3, 'hair', 'tóc; lông', 'noun', '[{"en":"She has long black hair and brown eyes.","vi":"Cô ấy có mái tóc đen dài và đôi mắt nâu."},{"en":"I need to get my hair cut before the wedding.","vi":"Tôi cần đi cắt tóc trước đám cưới."},{"en":"There is cat hair all over the sofa.","vi":"Lông mèo dính khắp ghế sofa."}]', '[{"phrase":"long hair"},{"phrase":"short hair"},{"phrase":"wash your hair"},{"phrase":"brush your hair"}]', 'Chỉ tóc nói chung: không đếm được (her hair is long)', '/her/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hai/hair_/hair__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 4, 'male', 'nam; đực, trống', 'adjective', '[{"en":"Only two male students joined the dance class.","vi":"Chỉ có hai nam sinh tham gia lớp học nhảy."},{"en":"Is your new puppy male or female?","vi":"Chú chó con mới của bạn là đực hay cái?"},{"en":"The male bird has brighter feathers than the female.","vi":"Chim trống có bộ lông sặc sỡ hơn chim mái."}]', '[{"phrase":"male and female"},{"phrase":"male students"},{"phrase":"male friend"}]', 'male ≠ female (nữ; cái, mái)', '/meɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mal/male_/male__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 5, 'operate', 'vận hành, điều khiển; hoạt động; phẫu thuật', 'verb', '[{"en":"Only trained staff are allowed to operate this machine.","vi":"Chỉ nhân viên đã được đào tạo mới được phép vận hành máy này."},{"en":"The company operates in more than twenty countries.","vi":"Công ty hoạt động tại hơn hai mươi quốc gia."},{"en":"The doctors had to operate on his knee last week.","vi":"Tuần trước các bác sĩ đã phải phẫu thuật đầu gối của anh ấy."}]', '[{"phrase":"operate a machine"},{"phrase":"operate on"},{"phrase":"operate in"}]', 'operate on sb/sth: phẫu thuật cho ai/bộ phận nào', '/ˈɑːpəreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ope/opera/operate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 6, 'reflect', 'phản ánh; phản chiếu; suy ngẫm', 'verb', '[{"en":"Her choice of clothes reflects her personality.","vi":"Cách chọn quần áo của cô ấy phản ánh tính cách của cô ấy."},{"en":"The lake reflected the mountains like a mirror.","vi":"Mặt hồ phản chiếu những ngọn núi như một tấm gương."},{"en":"Take some time to reflect on what you have learned.","vi":"Hãy dành chút thời gian suy ngẫm về những gì bạn đã học."}]', '[{"phrase":"reflect on"},{"phrase":"reflect light"},{"phrase":"clearly reflect"}]', 'reflect on sth: suy ngẫm về điều gì', '/rɪˈflekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refle/reflect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 7, 'exercise', 'sự tập thể dục; bài tập', 'noun', '[{"en":"Regular exercise helps you sleep better at night.","vi":"Tập thể dục đều đặn giúp bạn ngủ ngon hơn vào ban đêm."},{"en":"I try to get some exercise every morning before work.","vi":"Tôi cố gắng tập thể dục mỗi sáng trước khi đi làm."},{"en":"For homework, please finish the grammar exercises on page ten.","vi":"Về nhà, các em hãy làm các bài tập ngữ pháp ở trang mười."}]', '[{"phrase":"regular exercise"},{"phrase":"get some exercise"},{"phrase":"do exercises"},{"phrase":"grammar exercises"}]', 'Tập thể dục: không đếm được; bài tập: đếm được', '/ˈeksərsaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exe/exerc/exercise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 8, 'useful', 'có ích, hữu ích', 'adjective', '[{"en":"Thank you, your advice was really useful.","vi":"Cảm ơn bạn, lời khuyên của bạn thật sự rất hữu ích."},{"en":"A dictionary is useful when you learn a new language.","vi":"Từ điển rất hữu ích khi bạn học một ngôn ngữ mới."},{"en":"She gave me some useful tips for the interview.","vi":"Cô ấy cho tôi vài mẹo hữu ích cho buổi phỏng vấn."}]', '[{"phrase":"very useful"},{"phrase":"useful information"},{"phrase":"useful tips"},{"phrase":"useful for"}]', NULL, '/ˈjuːsfl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/use/usefu/useful__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 9, 'restaurant', 'nhà hàng', 'noun', '[{"en":"We had dinner at a small Italian restaurant downtown.","vi":"Chúng tôi ăn tối ở một nhà hàng Ý nhỏ trong trung tâm thành phố."},{"en":"This restaurant is always busy on Friday nights.","vi":"Nhà hàng này lúc nào cũng đông khách vào tối thứ Sáu."},{"en":"Could you recommend a good restaurant near the hotel?","vi":"Bạn có thể giới thiệu một nhà hàng ngon gần khách sạn không?"}]', '[{"phrase":"go to a restaurant"},{"phrase":"Italian restaurant"},{"phrase":"restaurant owner"}]', NULL, '/ˈrestrɑːnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/resta/restaurant__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 10, 'income', 'thu nhập', 'noun', '[{"en":"Most of their income goes on rent and food.","vi":"Phần lớn thu nhập của họ dành cho tiền thuê nhà và thức ăn."},{"en":"She earns extra income by teaching English online.","vi":"Cô ấy kiếm thêm thu nhập bằng cách dạy tiếng Anh trực tuyến."},{"en":"Families on a low income can get help with school costs.","vi":"Các gia đình có thu nhập thấp có thể được hỗ trợ chi phí học tập."}]', '[{"phrase":"low income"},{"phrase":"high income"},{"phrase":"extra income"},{"phrase":"monthly income"}]', NULL, '/ˈɪnkʌm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inc/incom/income__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 11, 'property', 'tài sản; bất động sản, nhà đất', 'noun', '[{"en":"Students must not damage school property in any way.","vi":"Học sinh không được làm hư hại tài sản của trường dưới bất kỳ hình thức nào."},{"en":"Property prices in the city center have risen sharply.","vi":"Giá nhà đất ở trung tâm thành phố đã tăng mạnh."},{"en":"They bought a property near the beach last year.","vi":"Năm ngoái họ đã mua một bất động sản gần biển."}]', '[{"phrase":"private property"},{"phrase":"property prices"},{"phrase":"buy a property"}]', NULL, '/ˈprɑːpərti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prope/property__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 12, 'previous', 'trước, trước đó', 'adjective', '[{"en":"In my previous job, I worked very long hours.","vi":"Ở công việc trước, tôi phải làm việc rất nhiều giờ."},{"en":"The previous owners of the house left a piano behind.","vi":"Những người chủ trước của ngôi nhà đã để lại một cây đàn piano."},{"en":"She had met him on a previous visit to the city.","vi":"Cô ấy đã gặp anh ấy trong một lần đến thành phố trước đó."}]', '[{"phrase":"previous job"},{"phrase":"previous owner"},{"phrase":"previous year"},{"phrase":"previous experience"}]', NULL, '/ˈpriːviəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/previ/previous__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 13, 'dark', 'tối; sẫm, đậm (màu)', 'adjective', '[{"en":"It gets dark very early in winter.","vi":"Vào mùa đông trời tối rất sớm."},{"en":"The room was so dark that I couldn''t see anything.","vi":"Căn phòng tối đến mức tôi không nhìn thấy gì."},{"en":"He wore a dark blue suit to the meeting.","vi":"Anh ấy mặc bộ vest màu xanh đậm đến cuộc họp."}]', '[{"phrase":"get dark"},{"phrase":"dark blue"},{"phrase":"dark hair"}]', NULL, '/dɑːrk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dar/dark_/dark__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 14, 'imagine', 'tưởng tượng; hình dung', 'verb', '[{"en":"Imagine you are lying on a quiet beach.","vi":"Hãy tưởng tượng bạn đang nằm trên một bãi biển yên tĩnh."},{"en":"I can''t imagine living without my phone.","vi":"Tôi không thể tưởng tượng được cuộc sống không có điện thoại."},{"en":"The city was much bigger than I had imagined.","vi":"Thành phố lớn hơn nhiều so với những gì tôi đã hình dung."}]', '[{"phrase":"can''t imagine"},{"phrase":"try to imagine"},{"phrase":"imagine life without"}]', 'imagine + V-ing (imagine living)', '/ɪˈmædʒɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ima/imagi/imagine__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 15, 'earn', 'kiếm (tiền); xứng đáng có, giành được', 'verb', '[{"en":"He earns about two thousand dollars a month.","vi":"Anh ấy kiếm được khoảng hai nghìn đô la mỗi tháng."},{"en":"Many students earn money by working part-time.","vi":"Nhiều sinh viên kiếm tiền bằng cách làm thêm."},{"en":"After working so hard, you''ve earned a good rest.","vi":"Sau khi làm việc chăm chỉ như vậy, bạn xứng đáng được nghỉ ngơi thật tốt."}]', '[{"phrase":"earn money"},{"phrase":"earn a living"},{"phrase":"earn respect"}]', NULL, '/ɜːrn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ear/earn_/earn__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 16, 'daughter', 'con gái', 'noun', '[{"en":"They have two sons and a daughter.","vi":"Họ có hai con trai và một con gái."},{"en":"My daughter will start elementary school next September.","vi":"Con gái tôi sẽ vào tiểu học vào tháng Chín tới."},{"en":"She takes her daughter to piano lessons every Saturday.","vi":"Cô ấy đưa con gái đi học piano mỗi thứ Bảy."}]', '[{"phrase":"only daughter"},{"phrase":"eldest daughter"},{"phrase":"youngest daughter"}]', NULL, '/ˈdɔːtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dau/daugh/daughter__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 17, 'post', 'đăng (lên mạng); gửi (thư) qua bưu điện', 'verb', '[{"en":"She posted a photo of her new puppy online.","vi":"Cô ấy đã đăng ảnh chú chó con mới của mình lên mạng."},{"en":"The results will be posted on the school website tomorrow.","vi":"Kết quả sẽ được đăng trên trang web của trường vào ngày mai."},{"en":"I''ll post the letter on my way to work.","vi":"Tôi sẽ gửi lá thư trên đường đi làm."}]', '[{"phrase":"post a photo"},{"phrase":"post online"},{"phrase":"post a comment"},{"phrase":"post a letter"}]', 'Gửi thư: Anh: post · Mỹ: mail', '/pəʊst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/post_/post__1_us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 18, 'newspaper', 'báo, tờ báo', 'noun', '[{"en":"My grandfather reads the newspaper every morning with his coffee.","vi":"Ông tôi đọc báo mỗi sáng khi uống cà phê."},{"en":"I saw the job advertisement in a local newspaper.","vi":"Tôi thấy mẩu quảng cáo tuyển dụng trên một tờ báo địa phương."},{"en":"Her story appeared on the front page of the newspaper.","vi":"Câu chuyện của cô ấy xuất hiện trên trang nhất của tờ báo."}]', '[{"phrase":"read the newspaper"},{"phrase":"local newspaper"},{"phrase":"newspaper article"},{"phrase":"daily newspaper"}]', NULL, '/ˈnuːzpeɪpər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/new/newsp/newspaper__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 19, 'define', 'định nghĩa; xác định', 'verb', '[{"en":"Can you define this word in simple English?","vi":"Bạn có thể định nghĩa từ này bằng tiếng Anh đơn giản không?"},{"en":"It is hard to define what happiness really is.","vi":"Thật khó để định nghĩa hạnh phúc thực sự là gì."},{"en":"First, we need to clearly define the goals of the project.","vi":"Trước hết, chúng ta cần xác định rõ mục tiêu của dự án."}]', '[{"phrase":"clearly define"},{"phrase":"define a word"},{"phrase":"hard to define"}]', NULL, '/dɪˈfaɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/def/defin/define__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 20, 'conclusion', 'kết luận; phần kết', 'noun', '[{"en":"What conclusion did you reach after reading the report?","vi":"Bạn đã rút ra kết luận gì sau khi đọc bản báo cáo?"},{"en":"We came to the conclusion that the plan wouldn''t work.","vi":"Chúng tôi đi đến kết luận rằng kế hoạch đó sẽ không hiệu quả."},{"en":"Remember to write a short conclusion at the end of your essay.","vi":"Nhớ viết một đoạn kết ngắn ở cuối bài luận của bạn."}]', '[{"phrase":"come to a conclusion"},{"phrase":"reach a conclusion"},{"phrase":"draw a conclusion"},{"phrase":"in conclusion"}]', NULL, '/kənˈkluːʒn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconclusion__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 21, 'clock', 'đồng hồ (treo tường, để bàn)', 'noun', '[{"en":"The clock on the kitchen wall is five minutes fast.","vi":"Chiếc đồng hồ trên tường bếp chạy nhanh năm phút."},{"en":"I set my alarm clock for six o''clock.","vi":"Tôi đặt đồng hồ báo thức lúc sáu giờ."},{"en":"She kept looking at the clock during the boring meeting.","vi":"Cô ấy cứ nhìn đồng hồ suốt cuộc họp nhàm chán."}]', '[{"phrase":"alarm clock"},{"phrase":"look at the clock"},{"phrase":"wall clock"}]', 'clock (treo tường, để bàn) ≠ watch (đồng hồ đeo tay)', '/klɑːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clo/clock/clock__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 22, 'everybody', 'mọi người', 'pronoun', '[{"en":"Everybody in my family loves spicy food.","vi":"Mọi người trong gia đình tôi đều thích đồ ăn cay."},{"en":"Can everybody hear me at the back of the room?","vi":"Mọi người ở cuối phòng có nghe thấy tôi không?"},{"en":"Not everybody agrees with the new rules at work.","vi":"Không phải ai cũng đồng ý với các quy định mới ở chỗ làm."}]', '[{"phrase":"everybody else"},{"phrase":"everybody knows"},{"phrase":"not everybody"}]', 'Đi với động từ số ít: everybody knows', '/ˈevribɑːdi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eve/every/everybody__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 23, 'weekend', 'cuối tuần', 'noun', '[{"en":"What are you planning to do this weekend?","vi":"Bạn định làm gì vào cuối tuần này?"},{"en":"We spent the weekend at my grandparents'' farm.","vi":"Chúng tôi đã ở trang trại của ông bà tôi vào cuối tuần."},{"en":"The library is closed on weekends and public holidays.","vi":"Thư viện đóng cửa vào cuối tuần và các ngày lễ."}]', '[{"phrase":"this weekend"},{"phrase":"last weekend"},{"phrase":"on weekends"},{"phrase":"spend the weekend"}]', 'Mỹ: on the weekend · Anh: at the weekend', '/ˈwiːkend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wee/weeke/weekend__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 24, 'perform', 'biểu diễn; thực hiện; làm (tốt, kém)', 'verb', '[{"en":"The band will perform live in the park on Sunday.","vi":"Ban nhạc sẽ biểu diễn trực tiếp trong công viên vào Chủ nhật."},{"en":"This machine can perform several tasks at the same time.","vi":"Chiếc máy này có thể thực hiện nhiều việc cùng lúc."},{"en":"She performed very well in her final exams.","vi":"Cô ấy đã làm bài rất tốt trong các kỳ thi cuối kỳ."}]', '[{"phrase":"perform live"},{"phrase":"perform a task"},{"phrase":"perform well"}]', NULL, '/pərˈfɔːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perfo/perform__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 25, 'professional', 'chuyên nghiệp; chuyên môn', 'adjective', '[{"en":"He wants to become a professional soccer player.","vi":"Anh ấy muốn trở thành cầu thủ bóng đá chuyên nghiệp."},{"en":"The staff at the hotel were friendly and very professional.","vi":"Nhân viên khách sạn thân thiện và rất chuyên nghiệp."},{"en":"You should get professional advice before buying a house.","vi":"Bạn nên xin tư vấn chuyên môn trước khi mua nhà."}]', '[{"phrase":"professional advice"},{"phrase":"professional help"},{"phrase":"professional player"}]', NULL, '/prəˈfeʃənl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/profe/professional__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 26, 'debate', 'cuộc tranh luận, tranh biện; sự tranh cãi', 'noun', '[{"en":"The class had a lively debate about school uniforms.","vi":"Cả lớp đã có một cuộc tranh luận sôi nổi về đồng phục học sinh."},{"en":"Our team won the debate against the other school.","vi":"Đội chúng tôi đã thắng cuộc tranh biện với trường kia."},{"en":"There is a lot of debate about how much homework children need.","vi":"Có nhiều tranh cãi về việc trẻ em cần bao nhiêu bài tập về nhà."}]', '[{"phrase":"lively debate"},{"phrase":"heated debate"},{"phrase":"public debate"},{"phrase":"win a debate"}]', NULL, '/dɪˈbeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/deb/debat/debate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 27, 'memory', 'trí nhớ; kỷ niệm', 'noun', '[{"en":"My grandmother has a very good memory for names.","vi":"Bà tôi có trí nhớ rất tốt về tên người."},{"en":"I have a terrible memory, so I write everything down.","vi":"Trí nhớ của tôi rất tệ nên tôi ghi lại mọi thứ."},{"en":"I have happy memories of summers at the beach.","vi":"Tôi có những kỷ niệm vui về những mùa hè ở biển."}]', '[{"phrase":"good memory"},{"phrase":"bad memory"},{"phrase":"happy memories"},{"phrase":"childhood memories"}]', NULL, '/ˈmeməri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mem/memor/memory__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 28, 'green', 'xanh lá cây; thân thiện với môi trường', 'adjective', '[{"en":"She was wearing a light green dress.","vi":"Cô ấy mặc một chiếc váy màu xanh lá nhạt."},{"en":"The hills are so green after the spring rain.","vi":"Những ngọn đồi thật xanh tươi sau cơn mưa xuân."},{"en":"The company is trying to be greener by using less plastic.","vi":"Công ty đang cố gắng thân thiện với môi trường hơn bằng cách dùng ít nhựa."}]', '[{"phrase":"light green"},{"phrase":"dark green"},{"phrase":"green tea"}]', NULL, '/ɡriːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gre/green/green__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-15', 29, 'song', 'bài hát', 'noun', '[{"en":"This is my favorite song from the album.","vi":"Đây là bài hát tôi thích nhất trong album."},{"en":"The children sang a song for their teacher''s birthday.","vi":"Bọn trẻ hát một bài hát mừng sinh nhật cô giáo."},{"en":"I can''t get that song out of my head.","vi":"Bài hát đó cứ vang mãi trong đầu tôi."}]', '[{"phrase":"sing a song"},{"phrase":"favorite song"},{"phrase":"love song"},{"phrase":"pop song"}]', NULL, '/sɔːŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/son/song_/song_1_us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-16', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 16', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 16);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 1, 'object', 'đồ vật, vật thể; mục đích', 'noun', '[{"en":"She picked up a small metal object from the floor.","vi":"Cô ấy nhặt một vật nhỏ bằng kim loại lên từ sàn nhà."},{"en":"Nobody could identify the strange object in the sky.","vi":"Không ai có thể xác định được vật thể lạ trên bầu trời."},{"en":"The object of the game is to collect as many points as possible.","vi":"Mục đích của trò chơi là thu được càng nhiều điểm càng tốt."}]', '[{"phrase":"small object"},{"phrase":"everyday objects"},{"phrase":"object of the game"}]', NULL, '/ˈɑːbdʒɪkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obj/objec/object__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 2, 'maintain', 'duy trì, giữ; bảo dưỡng', 'verb', '[{"en":"It is hard to maintain a healthy weight when you work long hours.","vi":"Thật khó duy trì cân nặng hợp lý khi bạn làm việc nhiều giờ."},{"en":"We try to maintain good relations with all our neighbors.","vi":"Chúng tôi cố gắng giữ quan hệ tốt với tất cả hàng xóm."},{"en":"The city spends a lot of money maintaining its roads.","vi":"Thành phố chi rất nhiều tiền để bảo dưỡng đường sá."}]', '[{"phrase":"maintain good relations"},{"phrase":"maintain a healthy weight"},{"phrase":"well maintained"}]', NULL, '/meɪnˈteɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mai/maint/maintain__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 3, 'credit', 'tín dụng; sự ghi nhận công lao; tín chỉ', 'noun', '[{"en":"Can I pay by credit card, or do you only take cash?","vi":"Tôi có thể trả bằng thẻ tín dụng không, hay bạn chỉ nhận tiền mặt?"},{"en":"She deserves credit for all the hard work she put in.","vi":"Cô ấy xứng đáng được ghi nhận vì tất cả công sức đã bỏ ra."},{"en":"You need 120 credits to graduate from this program.","vi":"Bạn cần 120 tín chỉ để tốt nghiệp chương trình này."}]', '[{"phrase":"credit card"},{"phrase":"deserve credit"},{"phrase":"take credit for"}]', NULL, '/ˈkredɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cre/credi/credit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 4, 'ring', 'reo, rung (chuông); gọi điện thoại', 'verb', '[{"en":"The phone rang just as I was getting into the shower.","vi":"Điện thoại reo đúng lúc tôi vừa bước vào tắm."},{"en":"Please ring the bell if you need any help.","vi":"Vui lòng bấm chuông nếu bạn cần giúp đỡ."},{"en":"I''ll ring you tomorrow morning to confirm the time.","vi":"Sáng mai tôi sẽ gọi điện cho bạn để xác nhận giờ giấc."}]', '[{"phrase":"phone rings"},{"phrase":"ring the bell"},{"phrase":"ring the doorbell"}]', 'ring – rang – rung', '/rɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rin/ring_/ring__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 5, 'discover', 'khám phá; phát hiện', 'verb', '[{"en":"Scientists have discovered a new kind of fish in the river.","vi":"Các nhà khoa học đã phát hiện một loài cá mới ở con sông."},{"en":"We discovered a lovely little café near our hotel.","vi":"Chúng tôi đã khám phá ra một quán cà phê nhỏ xinh gần khách sạn."},{"en":"It took years for him to discover the truth about his family.","vi":"Anh ấy mất nhiều năm mới phát hiện ra sự thật về gia đình mình."}]', '[{"phrase":"discover the truth"},{"phrase":"newly discovered"},{"phrase":"discover that"}]', NULL, '/dɪˈskʌvər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/disco/discover__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 6, 'dead', 'chết; hết pin, không hoạt động', 'adjective', '[{"en":"Remove the dead leaves so the plant can grow better.","vi":"Hãy bỏ những chiếc lá chết đi để cây phát triển tốt hơn."},{"en":"The car won''t start because of a dead battery.","vi":"Xe không khởi động được vì bình ắc quy hết điện."},{"en":"My phone is dead, so I can''t call a taxi.","vi":"Điện thoại tôi hết pin nên tôi không gọi taxi được."}]', '[{"phrase":"dead leaves"},{"phrase":"dead battery"},{"phrase":"dead end"}]', NULL, '/ded/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dea/dead_/dead__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 7, 'afternoon', 'buổi chiều', 'noun', '[{"en":"I usually take a short nap in the afternoon.","vi":"Tôi thường chợp mắt một lát vào buổi chiều."},{"en":"Are you free on Friday afternoon for a quick meeting?","vi":"Chiều thứ Sáu bạn có rảnh để họp nhanh không?"},{"en":"We spent the whole afternoon walking around the old town.","vi":"Chúng tôi dành cả buổi chiều đi dạo quanh khu phố cổ."}]', '[{"phrase":"in the afternoon"},{"phrase":"this afternoon"},{"phrase":"Friday afternoon"},{"phrase":"late afternoon"}]', NULL, '/ˌæftərˈnuːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aft/after/afternoon__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 8, 'prefer', 'thích hơn', 'verb', '[{"en":"I prefer tea to coffee in the morning.","vi":"Buổi sáng tôi thích uống trà hơn cà phê."},{"en":"I would prefer to stay home tonight, if you don''t mind.","vi":"Tối nay tôi muốn ở nhà hơn, nếu bạn không phiền."},{"en":"Most of our customers prefer paying by card.","vi":"Phần lớn khách hàng của chúng tôi thích trả bằng thẻ hơn."}]', '[{"phrase":"would prefer"},{"phrase":"much prefer"},{"phrase":"prefer tea to coffee"}]', 'prefer A to B · preferred (gấp đôi r)', '/prɪˈfɜːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/prefe/prefer__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 9, 'extend', 'kéo dài; gia hạn; mở rộng', 'verb', '[{"en":"We decided to extend our stay in the city by three days.","vi":"Chúng tôi quyết định kéo dài thời gian ở lại thành phố thêm ba ngày."},{"en":"The teacher agreed to extend the deadline by one week.","vi":"Giáo viên đồng ý gia hạn thời hạn nộp bài thêm một tuần."},{"en":"The school plans to extend the library next year.","vi":"Nhà trường dự định mở rộng thư viện vào năm sau."}]', '[{"phrase":"extend the deadline"},{"phrase":"extend your stay"},{"phrase":"extend a contract"}]', NULL, '/ɪkˈstend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ext/exten/extend__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 10, 'possibility', 'khả năng; sự có thể', 'noun', '[{"en":"There is a possibility that it will rain this afternoon.","vi":"Có khả năng chiều nay trời sẽ mưa."},{"en":"Have you considered the possibility of studying abroad?","vi":"Bạn đã tính đến khả năng đi du học chưa?"},{"en":"We can''t rule out the possibility of delays.","vi":"Chúng ta không thể loại trừ khả năng bị chậm trễ."}]', '[{"phrase":"real possibility"},{"phrase":"strong possibility"},{"phrase":"rule out the possibility"},{"phrase":"consider the possibility"}]', NULL, '/ˌpɑːsəˈbɪləti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/possi/possibility__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 11, 'direction', 'hướng; sự chỉ dẫn', 'noun', '[{"en":"Excuse me, which direction is the train station?","vi":"Xin lỗi, ga tàu ở hướng nào vậy?"},{"en":"We were walking in the wrong direction for twenty minutes.","vi":"Chúng tôi đã đi sai hướng suốt hai mươi phút."},{"en":"Follow the directions on the box carefully.","vi":"Hãy làm theo kỹ các chỉ dẫn trên hộp."}]', '[{"phrase":"opposite direction"},{"phrase":"wrong direction"},{"phrase":"ask for directions"}]', 'directions (số nhiều) = lời chỉ đường, hướng dẫn', '/dəˈrekʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dir/direc/direction__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 12, 'facility', 'cơ sở vật chất; tiện nghi', 'noun', '[{"en":"The hotel has excellent sports facilities, including a pool.","vi":"Khách sạn có cơ sở vật chất thể thao rất tốt, gồm cả hồ bơi."},{"en":"Our school recently opened a new research facility.","vi":"Trường chúng tôi vừa mở một cơ sở nghiên cứu mới."},{"en":"Are there any parking facilities near the hospital?","vi":"Gần bệnh viện có bãi đỗ xe nào không?"}]', '[{"phrase":"sports facilities"},{"phrase":"research facility"},{"phrase":"parking facilities"},{"phrase":"medical facilities"}]', 'thường dùng số nhiều: facilities', '/fəˈsɪləti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/facil/facility__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 13, 'variety', 'sự đa dạng; loại, giống', 'noun', '[{"en":"The market sells a wide variety of fresh fruit.","vi":"Chợ bán rất nhiều loại trái cây tươi."},{"en":"I like my job because it offers plenty of variety.","vi":"Tôi thích công việc của mình vì nó rất đa dạng."},{"en":"This variety of apple is sweet and very crunchy.","vi":"Giống táo này ngọt và rất giòn."}]', '[{"phrase":"a wide variety of"},{"phrase":"a variety of"},{"phrase":"great variety"}]', NULL, '/vəˈraɪəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/var/varie/variety__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 14, 'daily', 'hằng ngày', 'adjective', '[{"en":"Exercise has become part of my daily routine.","vi":"Tập thể dục đã trở thành một phần thói quen hằng ngày của tôi."},{"en":"She writes about her daily life on a small blog.","vi":"Cô ấy viết về cuộc sống hằng ngày của mình trên một blog nhỏ."},{"en":"We check the equipment on a daily basis.","vi":"Chúng tôi kiểm tra thiết bị hằng ngày."}]', '[{"phrase":"daily routine"},{"phrase":"daily life"},{"phrase":"on a daily basis"},{"phrase":"daily newspaper"}]', NULL, '/ˈdeɪli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dai/daily/daily__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 15, 'clothes', 'quần áo', 'noun', '[{"en":"I need to buy some new clothes for work.","vi":"Tôi cần mua vài bộ quần áo mới để đi làm."},{"en":"Take off your wet clothes before you catch a cold.","vi":"Cởi quần áo ướt ra kẻo bạn bị cảm lạnh."},{"en":"She always wears comfortable clothes when she travels.","vi":"Cô ấy luôn mặc quần áo thoải mái khi đi du lịch."}]', '[{"phrase":"new clothes"},{"phrase":"wet clothes"},{"phrase":"change clothes"},{"phrase":"casual clothes"}]', 'luôn ở dạng số nhiều', '/kləʊðz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clo/cloth/clothes__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 16, 'screen', 'màn hình', 'noun', '[{"en":"My phone screen cracked when I dropped it.","vi":"Màn hình điện thoại của tôi bị nứt khi tôi làm rơi nó."},{"en":"Doctors say children should have less screen time each day.","vi":"Bác sĩ khuyên trẻ em nên dành ít thời gian nhìn màn hình hơn mỗi ngày."},{"en":"Can you share your screen so we can all see the slides?","vi":"Bạn chia sẻ màn hình để mọi người cùng xem slide được không?"}]', '[{"phrase":"computer screen"},{"phrase":"touch screen"},{"phrase":"screen time"},{"phrase":"share your screen"}]', NULL, '/skriːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/scr/scree/screen__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 17, 'track', 'đường mòn; đường chạy; bài hát (trong album)', 'noun', '[{"en":"We followed a narrow track through the forest.","vi":"Chúng tôi đi theo một con đường mòn hẹp xuyên qua khu rừng."},{"en":"The athletes ran four laps around the running track.","vi":"Các vận động viên chạy bốn vòng quanh đường chạy."},{"en":"This is my favorite track on the whole album.","vi":"Đây là bài hát tôi thích nhất trong cả album."}]', '[{"phrase":"running track"},{"phrase":"dirt track"},{"phrase":"keep track of"}]', NULL, '/træk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/track/track__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 18, 'dance', 'nhảy, khiêu vũ', 'verb', '[{"en":"My grandparents still love to dance together at parties.","vi":"Ông bà tôi vẫn thích nhảy cùng nhau trong các bữa tiệc."},{"en":"We danced all night at my cousin''s wedding.","vi":"Chúng tôi đã nhảy suốt đêm ở đám cưới của anh họ tôi."},{"en":"Can you teach me how to dance the salsa?","vi":"Bạn có thể dạy tôi nhảy salsa không?"}]', '[{"phrase":"dance together"},{"phrase":"dance to the music"},{"phrase":"learn to dance"}]', NULL, '/dæns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dan/dance/dance__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 19, 'completely', 'hoàn toàn', 'adverb', '[{"en":"I completely forgot about our meeting this morning.","vi":"Tôi hoàn toàn quên mất cuộc họp của chúng ta sáng nay."},{"en":"The new building is completely different from the old one.","vi":"Tòa nhà mới hoàn toàn khác với tòa nhà cũ."},{"en":"Make sure the paint is completely dry before you touch it.","vi":"Hãy đảm bảo sơn đã khô hoàn toàn trước khi bạn chạm vào."}]', '[{"phrase":"completely different"},{"phrase":"completely forget"},{"phrase":"completely wrong"}]', NULL, '/kəmˈpliːtli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/completely__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 20, 'female', 'nữ; (giống) cái', 'adjective', '[{"en":"Most of the students in my class are female.","vi":"Phần lớn học sinh trong lớp tôi là nữ."},{"en":"The female bird sits on the eggs to keep them warm.","vi":"Chim mái nằm ấp trứng để giữ ấm cho trứng."},{"en":"The company wants to hire more female engineers.","vi":"Công ty muốn tuyển thêm nhiều kỹ sư nữ."}]', '[{"phrase":"female students"},{"phrase":"female employees"},{"phrase":"female voice"}]', NULL, '/ˈfiːmeɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fem/femal/female__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 21, 'responsibility', 'trách nhiệm', 'noun', '[{"en":"Taking care of the dog is my brother''s responsibility.","vi":"Chăm sóc con chó là trách nhiệm của anh trai tôi."},{"en":"Parents have a responsibility to keep their children safe.","vi":"Cha mẹ có trách nhiệm giữ cho con cái được an toàn."},{"en":"She took full responsibility for the mistake.","vi":"Cô ấy nhận toàn bộ trách nhiệm về sai lầm đó."}]', '[{"phrase":"take responsibility for"},{"phrase":"full responsibility"},{"phrase":"a sense of responsibility"}]', 'responsibility for sth', '/rɪˌspɑːnsəˈbɪləti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respo/responsibility__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 22, 'original', 'ban đầu, gốc; độc đáo', 'adjective', '[{"en":"The original plan was to leave on Monday.","vi":"Kế hoạch ban đầu là khởi hành vào thứ Hai."},{"en":"Please keep the original receipt in case you need a refund.","vi":"Vui lòng giữ hóa đơn gốc phòng khi bạn cần hoàn tiền."},{"en":"Her ideas are always fresh and original.","vi":"Ý tưởng của cô ấy luôn mới mẻ và độc đáo."}]', '[{"phrase":"original plan"},{"phrase":"original version"},{"phrase":"original idea"}]', NULL, '/əˈrɪdʒənl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ori/origi/original__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 23, 'sister', 'chị gái; em gái', 'noun', '[{"en":"My older sister lives in another city with her husband.","vi":"Chị gái tôi sống ở một thành phố khác cùng chồng."},{"en":"I share a bedroom with my little sister.","vi":"Tôi ở chung phòng ngủ với em gái."},{"en":"Do you have any brothers or sisters?","vi":"Bạn có anh chị em nào không?"}]', '[{"phrase":"older sister"},{"phrase":"younger sister"},{"phrase":"little sister"},{"phrase":"big sister"}]', 'older sister = chị gái · younger sister = em gái', '/ˈsɪstər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sis/siste/sister__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 24, 'rock', 'đá, tảng đá; nhạc rock', 'noun', '[{"en":"We sat on a large rock and watched the sunset.","vi":"Chúng tôi ngồi trên một tảng đá lớn ngắm hoàng hôn."},{"en":"Be careful, the rocks near the water are slippery.","vi":"Cẩn thận nhé, mấy tảng đá gần mép nước trơn lắm."},{"en":"My dad listens to rock music while he cooks.","vi":"Bố tôi nghe nhạc rock trong lúc nấu ăn."}]', '[{"phrase":"rock music"},{"phrase":"rock band"},{"phrase":"large rock"}]', NULL, '/rɑːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/roc/rock_/rock__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 25, 'dream', 'giấc mơ; ước mơ', 'noun', '[{"en":"I had a strange dream about flying last night.","vi":"Đêm qua tôi có một giấc mơ kỳ lạ về việc bay."},{"en":"Her dream is to open a small bakery one day.","vi":"Ước mơ của cô ấy là một ngày nào đó mở một tiệm bánh nhỏ."},{"en":"Working abroad was a dream come true for him.","vi":"Được làm việc ở nước ngoài là giấc mơ thành hiện thực của anh ấy."}]', '[{"phrase":"have a dream"},{"phrase":"bad dream"},{"phrase":"dream come true"},{"phrase":"dream job"}]', NULL, '/driːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dre/dream/dream__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 26, 'nor', 'cũng không', 'conjunction', '[{"en":"Neither my brother nor I can swim very well.","vi":"Cả anh trai tôi và tôi đều không bơi giỏi lắm."},{"en":"He doesn''t eat meat, nor does he drink milk.","vi":"Anh ấy không ăn thịt, cũng không uống sữa."},{"en":"The hotel was neither cheap nor very comfortable.","vi":"Khách sạn không rẻ mà cũng chẳng thoải mái lắm."}]', '[{"phrase":"neither ... nor"},{"phrase":"nor do I"}]', 'neither A nor B · nor đứng đầu mệnh đề thì đảo trợ động từ', '/nɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/nor__/nor__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 27, 'university', 'trường đại học', 'noun', '[{"en":"My cousin studies medicine at a large university.","vi":"Anh họ tôi học y ở một trường đại học lớn."},{"en":"She was the first in her family to go to university.","vi":"Cô ấy là người đầu tiên trong gia đình được học đại học."},{"en":"The university library stays open until midnight during exams.","vi":"Thư viện trường đại học mở cửa đến nửa đêm trong mùa thi."}]', '[{"phrase":"go to university"},{"phrase":"university student"},{"phrase":"university degree"},{"phrase":"university library"}]', NULL, '/ˌjuːnɪˈvɜːrsəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unive/university__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 28, 'easily', 'dễ dàng', 'adverb', '[{"en":"He gets angry very easily when he is tired.","vi":"Anh ấy rất dễ nổi nóng khi mệt."},{"en":"She passed the exam easily and got the highest score.","vi":"Cô ấy dễ dàng vượt qua kỳ thi và đạt điểm cao nhất."},{"en":"You can easily make this dish at home in twenty minutes.","vi":"Bạn có thể dễ dàng làm món này ở nhà trong hai mươi phút."}]', '[{"phrase":"can easily"},{"phrase":"very easily"},{"phrase":"easily accessible"}]', NULL, '/ˈiːzəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/eas/easil/easily__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-16', 29, 'agency', 'đại lý; cơ quan', 'noun', '[{"en":"We booked our trip through a travel agency.","vi":"Chúng tôi đặt chuyến đi qua một đại lý du lịch."},{"en":"She works for an advertising agency in the city center.","vi":"Cô ấy làm việc cho một công ty quảng cáo ở trung tâm thành phố."},{"en":"A government agency is checking the safety of the water.","vi":"Một cơ quan chính phủ đang kiểm tra độ an toàn của nguồn nước."}]', '[{"phrase":"travel agency"},{"phrase":"advertising agency"},{"phrase":"government agency"},{"phrase":"employment agency"}]', NULL, '/ˈeɪdʒənsi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/age/agenc/agency__us_2.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-2-17', 'ngsl-2', 'Thông dụng 501–1.000 · Bộ 17', 'New General Service List, thứ hạng 501–1.000', '#3da9fc', 'BookOpen', 17);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 1, 'dollar', 'đô la', 'noun', '[{"en":"This shirt only cost me ten dollars at the market.","vi":"Chiếc áo này tôi mua ở chợ chỉ mất mười đô la."},{"en":"Can you lend me twenty dollars until Friday?","vi":"Bạn cho tôi mượn hai mươi đô la đến thứ Sáu được không?"},{"en":"They spent millions of dollars on the new hospital.","vi":"Họ đã chi hàng triệu đô la cho bệnh viện mới."}]', '[{"phrase":"ten dollars"},{"phrase":"a million dollars"},{"phrase":"the US dollar"}]', NULL, '/ˈdɑːlər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dol/dolla/dollar__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 2, 'garden', 'vườn', 'noun', '[{"en":"My grandmother grows tomatoes and herbs in her garden.","vi":"Bà tôi trồng cà chua và rau thơm trong vườn."},{"en":"The children love playing in the garden after school.","vi":"Bọn trẻ rất thích chơi trong vườn sau giờ học."},{"en":"We had lunch in a small garden behind the restaurant.","vi":"Chúng tôi ăn trưa trong một khu vườn nhỏ phía sau nhà hàng."}]', '[{"phrase":"vegetable garden"},{"phrase":"flower garden"},{"phrase":"in the garden"}]', NULL, '/ˈɡɑːrdn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gar/garde/garden__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 3, 'fix', 'sửa chữa; ấn định', 'verb', '[{"en":"My brother fixed my bike in less than an hour.","vi":"Anh trai tôi sửa xe đạp cho tôi chưa đến một tiếng."},{"en":"Can someone fix the printer before the meeting starts?","vi":"Có ai sửa được máy in trước khi cuộc họp bắt đầu không?"},{"en":"Let''s fix a date for the next team meeting.","vi":"Chúng ta hãy ấn định ngày cho buổi họp nhóm tới nhé."}]', '[{"phrase":"fix a problem"},{"phrase":"fix a date"},{"phrase":"fix a price"}]', NULL, '/fɪks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fix/fix__/fix__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 4, 'ahead', 'phía trước; trước (thời gian)', 'adverb', '[{"en":"Go straight ahead and turn left at the bank.","vi":"Đi thẳng về phía trước rồi rẽ trái ở ngân hàng."},{"en":"We need to plan ahead for the holiday season.","vi":"Chúng ta cần lên kế hoạch trước cho mùa lễ."},{"en":"Our team finished the project two days ahead of schedule.","vi":"Nhóm chúng tôi hoàn thành dự án sớm hơn kế hoạch hai ngày."}]', '[{"phrase":"go ahead"},{"phrase":"plan ahead"},{"phrase":"ahead of schedule"},{"phrase":"straight ahead"}]', NULL, '/əˈhed/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ahe/ahead/ahead__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 5, 'cross', 'băng qua; bắt chéo', 'verb', '[{"en":"Always look both ways before you cross the street.","vi":"Luôn nhìn cả hai phía trước khi băng qua đường."},{"en":"It took us three hours to cross the border.","vi":"Chúng tôi mất ba tiếng để qua biên giới."},{"en":"He sat down on the sofa and crossed his legs.","vi":"Anh ấy ngồi xuống ghế sofa và bắt chéo chân."}]', '[{"phrase":"cross the street"},{"phrase":"cross the road"},{"phrase":"cross the border"},{"phrase":"cross your legs"}]', NULL, '/krɔːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cro/cross/cross__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 6, 'yeah', 'ừ; vâng', 'exclamation', '[{"en":"Yeah, I think that''s a really good idea.","vi":"Ừ, tôi nghĩ đó là một ý rất hay."},{"en":"Yeah, I''ll be there around eight o''clock tonight.","vi":"Vâng, tối nay khoảng tám giờ tôi sẽ có mặt."},{"en":"Oh yeah, I forgot to tell you about the party.","vi":"À ừ, tôi quên kể với bạn về bữa tiệc."}]', '[{"phrase":"oh yeah"},{"phrase":"yeah, sure"},{"phrase":"yeah, right"}]', 'Cách nói thân mật của "yes"', '/jeə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/y/yea/yeah_/yeah__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 7, 'candidate', 'ứng viên; thí sinh', 'noun', '[{"en":"We interviewed five candidates for the manager position.","vi":"Chúng tôi đã phỏng vấn năm ứng viên cho vị trí quản lý."},{"en":"She is the strongest candidate for the job.","vi":"Cô ấy là ứng viên sáng giá nhất cho công việc này."},{"en":"Candidates must answer all the questions on the exam paper.","vi":"Thí sinh phải trả lời tất cả các câu hỏi trong đề thi."}]', '[{"phrase":"strong candidate"},{"phrase":"candidate for"},{"phrase":"suitable candidate"},{"phrase":"job candidate"}]', NULL, '/ˈkændɪdət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/can/candi/candidate__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 8, 'weight', 'cân nặng; trọng lượng', 'noun', '[{"en":"He has lost a lot of weight since last summer.","vi":"Anh ấy đã giảm cân nhiều từ mùa hè năm ngoái."},{"en":"What is the maximum weight for checked baggage?","vi":"Trọng lượng tối đa cho hành lý ký gửi là bao nhiêu?"},{"en":"Regular exercise can help you keep your weight under control.","vi":"Tập thể dục đều đặn có thể giúp bạn kiểm soát cân nặng."}]', '[{"phrase":"lose weight"},{"phrase":"gain weight"},{"phrase":"put on weight"},{"phrase":"maximum weight"}]', NULL, '/weɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wei/weigh/weight__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 9, 'legal', 'hợp pháp; (thuộc) pháp lý', 'adjective', '[{"en":"Is it legal to park on this side of the street?","vi":"Đỗ xe ở bên này đường có hợp pháp không?"},{"en":"The company hired a lawyer to get legal advice.","vi":"Công ty đã thuê luật sư để được tư vấn pháp lý."},{"en":"They decided to take legal action against the builder.","vi":"Họ quyết định khởi kiện người thợ xây."}]', '[{"phrase":"legal advice"},{"phrase":"legal action"},{"phrase":"legal system"},{"phrase":"perfectly legal"}]', 'legal ≠ illegal (bất hợp pháp)', '/ˈliːɡl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/leg/legal/legal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 10, 'proposal', 'đề xuất; lời cầu hôn', 'noun', '[{"en":"The manager accepted our proposal for a shorter workweek.","vi":"Quản lý đã chấp nhận đề xuất rút ngắn tuần làm việc của chúng tôi."},{"en":"Please send me your project proposal by Friday.","vi":"Vui lòng gửi cho tôi bản đề xuất dự án trước thứ Sáu."},{"en":"She said yes to his marriage proposal on the beach.","vi":"Cô ấy đã nhận lời cầu hôn của anh ấy trên bãi biển."}]', '[{"phrase":"accept a proposal"},{"phrase":"reject a proposal"},{"phrase":"marriage proposal"},{"phrase":"proposal for"}]', NULL, '/prəˈpəʊzl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/propo/proposal__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 11, 'version', 'phiên bản', 'noun', '[{"en":"Have you downloaded the latest version of the app?","vi":"Bạn đã tải phiên bản mới nhất của ứng dụng chưa?"},{"en":"I prefer the original version of this song.","vi":"Tôi thích phiên bản gốc của bài hát này hơn."},{"en":"My sister told me a different version of the story.","vi":"Chị tôi kể cho tôi một phiên bản khác của câu chuyện."}]', '[{"phrase":"latest version"},{"phrase":"new version"},{"phrase":"original version"},{"phrase":"different version"}]', NULL, '/ˈvɜːrʒn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/ver/versi/version__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 12, 'conversation', 'cuộc trò chuyện; hội thoại', 'noun', '[{"en":"We had a long conversation about our plans for the future.","vi":"Chúng tôi đã có một cuộc trò chuyện dài về dự định tương lai."},{"en":"She tried to start a conversation with the new student.","vi":"Cô ấy cố gắng bắt chuyện với bạn học sinh mới."},{"en":"Practicing conversation with friends improved my English a lot.","vi":"Luyện hội thoại với bạn bè đã giúp tiếng Anh của tôi tiến bộ nhiều."}]', '[{"phrase":"have a conversation"},{"phrase":"start a conversation"},{"phrase":"phone conversation"},{"phrase":"conversation with"}]', NULL, '/ˌkɑːnvərˈseɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconversation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 13, 'somebody', 'ai đó; người nào đó', 'pronoun', '[{"en":"Somebody left their umbrella in the meeting room.","vi":"Ai đó đã để quên ô trong phòng họp."},{"en":"Can somebody help me carry these boxes upstairs?","vi":"Có ai giúp tôi mang mấy cái thùng này lên lầu không?"},{"en":"I need to talk to somebody about this problem.","vi":"Tôi cần nói chuyện với ai đó về vấn đề này."}]', '[{"phrase":"somebody else"},{"phrase":"talk to somebody"},{"phrase":"somebody who"}]', '= someone', '/ˈsʌmbədi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/som/someb/somebody__us_3_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 14, 'pound', 'bảng Anh; pao', 'noun', '[{"en":"The train ticket to London cost me ten pounds.","vi":"Vé tàu đi London tốn của tôi mười bảng Anh."},{"en":"I bought two pounds of apples at the market.","vi":"Tôi đã mua hai pao táo ở chợ."},{"en":"The baby weighed seven pounds when she was born.","vi":"Em bé nặng bảy pao lúc mới sinh."}]', '[{"phrase":"ten pounds"},{"phrase":"a pound of"},{"phrase":"the British pound"}]', '1 pound (pao) ≈ 0,45 kg', '/paʊnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pou/pound/pound__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 15, 'magazine', 'tạp chí', 'noun', '[{"en":"She buys a fashion magazine every month.","vi":"Tháng nào cô ấy cũng mua một cuốn tạp chí thời trang."},{"en":"My photo appeared on the cover of a travel magazine.","vi":"Ảnh của tôi xuất hiện trên bìa một tạp chí du lịch."},{"en":"There were some old magazines on the table in the waiting room.","vi":"Có vài cuốn tạp chí cũ trên bàn trong phòng chờ."}]', '[{"phrase":"fashion magazine"},{"phrase":"magazine article"},{"phrase":"magazine cover"}]', NULL, '/ˈmæɡəziːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mag/magaz/magazine__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 16, 'shape', 'hình dạng; thể trạng', 'noun', '[{"en":"The cake was made in the shape of a heart.","vi":"Chiếc bánh được làm theo hình trái tim."},{"en":"What shape is the table, round or square?","vi":"Cái bàn có hình gì, tròn hay vuông?"},{"en":"My father is in good shape for his age.","vi":"Bố tôi có thể trạng tốt so với tuổi của ông."}]', '[{"phrase":"in the shape of"},{"phrase":"in good shape"},{"phrase":"get in shape"},{"phrase":"round shape"}]', NULL, '/ʃeɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/shape/shape__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 17, 'sea', 'biển', 'noun', '[{"en":"Our hotel room had a beautiful view of the sea.","vi":"Phòng khách sạn của chúng tôi nhìn ra biển rất đẹp."},{"en":"The children swam in the sea all afternoon.","vi":"Bọn trẻ bơi ở biển suốt cả buổi chiều."},{"en":"Most of the fish we eat comes from the sea.","vi":"Phần lớn cá chúng ta ăn đến từ biển."}]', '[{"phrase":"by the sea"},{"phrase":"in the sea"},{"phrase":"sea level"},{"phrase":"at sea"}]', NULL, '/siː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sea/sea__/sea__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 18, 'immediately', 'ngay lập tức', 'adverb', '[{"en":"Please call me immediately if you have any problems.","vi":"Hãy gọi cho tôi ngay nếu bạn gặp bất kỳ vấn đề gì."},{"en":"She recognized her old teacher immediately when he walked in.","vi":"Cô ấy nhận ra thầy giáo cũ ngay khi thầy bước vào."},{"en":"The pain went away almost immediately after I took the medicine.","vi":"Cơn đau hết gần như ngay lập tức sau khi tôi uống thuốc."}]', '[{"phrase":"almost immediately"},{"phrase":"immediately after"},{"phrase":"leave immediately"}]', NULL, '/ɪˈmiːdiətli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imm/immed/immediately__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 19, 'welcome', 'chào đón; hoan nghênh', 'verb', '[{"en":"Our hosts warmly welcomed us with hot tea.","vi":"Chủ nhà nồng nhiệt chào đón chúng tôi bằng trà nóng."},{"en":"The school welcomes new students every September.","vi":"Trường chào đón học sinh mới vào mỗi tháng Chín."},{"en":"We welcome any ideas that can improve our service.","vi":"Chúng tôi hoan nghênh mọi ý tưởng giúp cải thiện dịch vụ."}]', '[{"phrase":"warmly welcome"},{"phrase":"welcome guests"},{"phrase":"welcome the idea"}]', 'You''re welcome = Không có gì (đáp lời cảm ơn)', '/ˈwelkəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wel/welco/welcome__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 20, 'smile', 'mỉm cười', 'verb', '[{"en":"The baby smiled when she saw her mother.","vi":"Em bé mỉm cười khi nhìn thấy mẹ."},{"en":"He always smiles at me when we meet in the hallway.","vi":"Anh ấy luôn mỉm cười với tôi khi chúng tôi gặp nhau ở hành lang."},{"en":"Try to smile more during your job interview.","vi":"Hãy cố gắng mỉm cười nhiều hơn trong buổi phỏng vấn xin việc."}]', '[{"phrase":"smile at"},{"phrase":"smile back"},{"phrase":"smile broadly"}]', NULL, '/smaɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/smi/smile/smile__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 21, 'communication', 'sự giao tiếp; liên lạc', 'noun', '[{"en":"Good communication is important in any relationship.","vi":"Giao tiếp tốt rất quan trọng trong bất kỳ mối quan hệ nào."},{"en":"Our team uses email for most communication with clients.","vi":"Nhóm chúng tôi dùng email cho hầu hết việc liên lạc với khách hàng."},{"en":"Communication was difficult because nobody spoke the local language.","vi":"Việc giao tiếp rất khó khăn vì không ai nói được tiếng địa phương."}]', '[{"phrase":"good communication"},{"phrase":"communication skills"},{"phrase":"lack of communication"},{"phrase":"means of communication"}]', NULL, '/kəˌmjuːnɪˈkeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commu/communication__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 22, 'agent', 'đại lý; người môi giới', 'noun', '[{"en":"Our travel agent booked the flights and the hotel.","vi":"Đại lý du lịch đã đặt vé máy bay và khách sạn cho chúng tôi."},{"en":"We found this apartment through a real estate agent.","vi":"Chúng tôi tìm được căn hộ này qua một người môi giới bất động sản."},{"en":"The insurance agent explained every part of the contract to us.","vi":"Đại lý bảo hiểm đã giải thích cho chúng tôi từng phần của hợp đồng."}]', '[{"phrase":"travel agent"},{"phrase":"real estate agent"},{"phrase":"insurance agent"}]', NULL, '/ˈeɪdʒənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/age/agent/agent__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 23, 'traditional', 'truyền thống', 'adjective', '[{"en":"We ate traditional food at the Lunar New Year festival.","vi":"Chúng tôi ăn các món truyền thống trong dịp Tết Nguyên đán."},{"en":"She wore a traditional dress to her sister''s wedding.","vi":"Cô ấy mặc trang phục truyền thống đến dự đám cưới của chị gái."},{"en":"Some parents still prefer traditional ways of teaching children.","vi":"Một số phụ huynh vẫn thích cách dạy con truyền thống hơn."}]', '[{"phrase":"traditional food"},{"phrase":"traditional dress"},{"phrase":"traditional music"},{"phrase":"traditional way"}]', NULL, '/trəˈdɪʃənl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/tradi/traditional__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 24, 'replace', 'thay thế; thay', 'verb', '[{"en":"I need to replace the battery in my watch.","vi":"Tôi cần thay pin cho đồng hồ."},{"en":"Many workers worry that machines will replace them.","vi":"Nhiều công nhân lo rằng máy móc sẽ thay thế họ."},{"en":"The old bridge was replaced by a new one.","vi":"Cây cầu cũ đã được thay bằng một cây cầu mới."}]', '[{"phrase":"replace the battery"},{"phrase":"replace with"},{"phrase":"completely replace"}]', 'replace A with B = thay A bằng B', '/rɪˈpleɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repla/replace__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 25, 'judge', 'thẩm phán; giám khảo', 'noun', '[{"en":"The judge listened carefully to both sides before deciding.","vi":"Thẩm phán lắng nghe kỹ cả hai bên trước khi quyết định."},{"en":"She was one of the judges in the singing competition.","vi":"Cô ấy là một trong những giám khảo của cuộc thi hát."},{"en":"A panel of judges will choose the winner next week.","vi":"Một hội đồng giám khảo sẽ chọn ra người chiến thắng vào tuần sau."}]', '[{"phrase":"panel of judges"},{"phrase":"the judge''s decision"}]', 'Động từ judge = đánh giá, phán xét', '/dʒʌdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/j/jud/judge/judge__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 26, 'suddenly', 'đột nhiên; bỗng nhiên', 'adverb', '[{"en":"Suddenly, all the lights in the building went out.","vi":"Đột nhiên, tất cả đèn trong tòa nhà đều tắt."},{"en":"It suddenly started raining while we were walking home.","vi":"Trời bỗng đổ mưa khi chúng tôi đang đi bộ về nhà."},{"en":"The car in front of us suddenly stopped.","vi":"Chiếc xe phía trước chúng tôi đột nhiên dừng lại."}]', '[{"phrase":"suddenly stop"},{"phrase":"suddenly realize"},{"phrase":"suddenly appear"}]', NULL, '/ˈsʌdənli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sud/sudde/suddenly__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 27, 'generation', 'thế hệ', 'noun', '[{"en":"Three generations of my family live in the same house.","vi":"Ba thế hệ trong gia đình tôi sống chung một nhà."},{"en":"The younger generation spends a lot of time online.","vi":"Thế hệ trẻ dành rất nhiều thời gian trên mạng."},{"en":"This recipe has been passed down from generation to generation.","vi":"Công thức này đã được truyền từ thế hệ này sang thế hệ khác."}]', '[{"phrase":"younger generation"},{"phrase":"older generation"},{"phrase":"future generations"},{"phrase":"from generation to generation"}]', NULL, '/ˌdʒenəˈreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gener/generation__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 28, 'estimate', 'ước tính; ước lượng', 'verb', '[{"en":"We estimate that the repairs will cost about five hundred dollars.","vi":"Chúng tôi ước tính việc sửa chữa sẽ tốn khoảng năm trăm đô la."},{"en":"Can you estimate the cost of painting the whole house?","vi":"Bạn có thể ước tính chi phí sơn cả ngôi nhà không?"},{"en":"Experts estimated the crowd at over ten thousand people.","vi":"Các chuyên gia ước tính đám đông có hơn mười nghìn người."}]', '[{"phrase":"estimate the cost"},{"phrase":"roughly estimate"},{"phrase":"it is estimated that"}]', 'Cũng là danh từ: an estimate = con số ước tính', '/ˈestɪmeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/est/estim/estimate__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-2-17', 29, 'favorite', 'yêu thích nhất', 'adjective', '[{"en":"What is your favorite movie of all time?","vi":"Bộ phim bạn thích nhất mọi thời đại là phim gì?"},{"en":"Pizza has always been my son''s favorite food.","vi":"Pizza luôn là món ăn con trai tôi thích nhất."},{"en":"This little cafe is our favorite place to meet on weekends.","vi":"Quán cà phê nhỏ này là nơi chúng tôi thích gặp nhau nhất vào cuối tuần."}]', '[{"phrase":"favorite food"},{"phrase":"favorite place"},{"phrase":"favorite movie"},{"phrase":"all-time favorite"}]', 'Anh: favourite · Mỹ: favorite', '/ˈfeɪvərɪt/', NULL, NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-01', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 1', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 1, 'difficulty', 'khó khăn; sự khó khăn', 'noun', '[{"en":"Many students have difficulty with English pronunciation at first.","vi":"Lúc đầu, nhiều học sinh gặp khó khăn với việc phát âm tiếng Anh."},{"en":"We found the hotel without any difficulty.","vi":"Chúng tôi tìm thấy khách sạn mà không gặp khó khăn gì."},{"en":"The company is having financial difficulties this year.","vi":"Năm nay công ty đang gặp khó khăn về tài chính."}]', '[{"phrase":"have difficulty"},{"phrase":"without difficulty"},{"phrase":"financial difficulties"},{"phrase":"great difficulty"}]', 'have difficulty (in) doing sth: gặp khó khăn khi làm gì', '/ˈdɪfɪkəlti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dif/diffi/difficulty__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 2, 'purchase', 'mua; mua sắm', 'verb', '[{"en":"You can purchase tickets online or at the station.","vi":"Bạn có thể mua vé trực tuyến hoặc tại nhà ga."},{"en":"They purchased their first home last year.","vi":"Năm ngoái họ đã mua căn nhà đầu tiên."},{"en":"Please keep your receipt after you purchase the item.","vi":"Vui lòng giữ lại hóa đơn sau khi mua hàng."}]', '[{"phrase":"purchase tickets"},{"phrase":"purchase goods"},{"phrase":"purchase a home"}]', 'trang trọng hơn buy', '/ˈpɜːrtʃəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pur/purch/purchase__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 3, 'shoot', 'bắn; sút (bóng); quay (phim), chụp (ảnh)', 'verb', '[{"en":"She shot an arrow and hit the center of the target.","vi":"Cô ấy bắn một mũi tên và trúng ngay giữa bia."},{"en":"He shot from far away and scored a great goal.","vi":"Anh ấy sút từ xa và ghi một bàn thắng đẹp."},{"en":"They shot the whole movie in just six weeks.","vi":"Họ quay toàn bộ bộ phim chỉ trong sáu tuần."}]', '[{"phrase":"shoot a movie"},{"phrase":"shoot a video"},{"phrase":"shoot an arrow"}]', 'shoot – shot – shot', '/ʃuːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shoot/shoot__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 4, 'announce', 'thông báo; công bố', 'verb', '[{"en":"The airline announced that the flight was delayed.","vi":"Hãng hàng không thông báo rằng chuyến bay bị hoãn."},{"en":"They will announce the winners on Friday evening.","vi":"Họ sẽ công bố những người thắng cuộc vào tối thứ Sáu."},{"en":"My sister announced her engagement at dinner last night.","vi":"Chị tôi thông báo tin đính hôn trong bữa tối hôm qua."}]', '[{"phrase":"announce the winners"},{"phrase":"officially announce"},{"phrase":"announce plans"}]', NULL, '/əˈnaʊns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ann/annou/announce__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 5, 'unless', 'trừ khi; nếu không', 'conjunction', '[{"en":"You can''t enter the building unless you have a pass.","vi":"Bạn không thể vào tòa nhà trừ khi có thẻ ra vào."},{"en":"Unless it rains, we''ll have lunch in the park.","vi":"Nếu trời không mưa, chúng ta sẽ ăn trưa trong công viên."},{"en":"Don''t wake me up unless it''s really necessary.","vi":"Đừng đánh thức tôi dậy trừ khi thật sự cần thiết."}]', '[{"phrase":"unless necessary"},{"phrase":"unless otherwise stated"}]', 'unless = if … not; không dùng will trong mệnh đề unless', '/ənˈles/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unl/unles/unless__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 6, 'independent', 'độc lập; tự lập', 'adjective', '[{"en":"My grandmother is ninety but still very independent.","vi":"Bà tôi đã chín mươi tuổi nhưng vẫn rất tự lập."},{"en":"We asked an independent expert to check the report.","vi":"Chúng tôi nhờ một chuyên gia độc lập kiểm tra bản báo cáo."},{"en":"My son wants to be financially independent before he turns twenty-five.","vi":"Con trai tôi muốn tự lập về tài chính trước tuổi hai mươi lăm."}]', '[{"phrase":"financially independent"},{"phrase":"independent of"},{"phrase":"completely independent"}]', 'independent of sb/sth: không phụ thuộc vào ai/cái gì', '/ˌɪndɪˈpendənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indep/independent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 7, 'recommend', 'giới thiệu; khuyên', 'verb', '[{"en":"Can you recommend a good restaurant near the hotel?","vi":"Bạn có thể giới thiệu một nhà hàng ngon gần khách sạn không?"},{"en":"The doctor recommended that I get more sleep.","vi":"Bác sĩ khuyên tôi nên ngủ nhiều hơn."},{"en":"I highly recommend this book to anyone learning English.","vi":"Tôi rất muốn giới thiệu cuốn sách này cho bất kỳ ai đang học tiếng Anh."}]', '[{"phrase":"highly recommend"},{"phrase":"strongly recommend"}]', 'recommend (that) sb do sth / recommend doing sth', '/ˌrekəˈmend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recom/recommend__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 8, 'survey', 'cuộc khảo sát', 'noun', '[{"en":"We carried out a survey of 500 customers last month.","vi":"Tháng trước chúng tôi đã thực hiện một cuộc khảo sát với 500 khách hàng."},{"en":"According to a recent survey, most people prefer working from home.","vi":"Theo một cuộc khảo sát gần đây, hầu hết mọi người thích làm việc tại nhà."},{"en":"Please take a few minutes to complete our survey.","vi":"Vui lòng dành vài phút để hoàn thành bản khảo sát của chúng tôi."}]', '[{"phrase":"carry out a survey"},{"phrase":"recent survey"},{"phrase":"complete a survey"}]', NULL, '/ˈsɜːrveɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sur/surve/survey__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 9, 'majority', 'phần lớn; đa số', 'noun', '[{"en":"The majority of students live near the campus.","vi":"Phần lớn sinh viên sống gần trường."},{"en":"The vast majority of our customers are very happy with the service.","vi":"Đại đa số khách hàng của chúng tôi rất hài lòng với dịch vụ."},{"en":"In our class, girls are in the majority.","vi":"Trong lớp chúng tôi, con gái chiếm đa số."}]', '[{"phrase":"the majority of"},{"phrase":"vast majority"},{"phrase":"in the majority"}]', 'majority (đa số) ≠ minority (thiểu số)', '/məˈdʒɔːrəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/maj/major/majority__us_3_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 10, 'stick', 'dán; dính; bám theo (kế hoạch)', 'verb', '[{"en":"She stuck a note on the fridge door.","vi":"Cô ấy dán một mẩu giấy nhắn lên cửa tủ lạnh."},{"en":"The rice stuck to the bottom of the pot.","vi":"Cơm bị dính vào đáy nồi."},{"en":"Let''s stick to the plan and leave at six.","vi":"Cứ theo đúng kế hoạch và đi lúc sáu giờ nhé."}]', '[{"phrase":"stick to"},{"phrase":"stick to the plan"},{"phrase":"stick together"},{"phrase":"get stuck"}]', 'stick – stuck – stuck', '/stɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sti/stick/stick__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 11, 'request', 'yêu cầu; lời đề nghị', 'noun', '[{"en":"The manager agreed to my request for a day off.","vi":"Quản lý đã đồng ý với đề nghị xin nghỉ một ngày của tôi."},{"en":"Free samples are available on request at the front desk.","vi":"Mẫu thử miễn phí được cung cấp tại quầy lễ tân khi có yêu cầu."},{"en":"We received hundreds of requests for more information.","vi":"Chúng tôi nhận được hàng trăm yêu cầu cung cấp thêm thông tin."}]', '[{"phrase":"make a request"},{"phrase":"request for"},{"phrase":"on request"},{"phrase":"receive a request"}]', 'request for sth', '/rɪˈkwest/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/req/reque/request__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 12, 'rich', 'giàu có; giàu (chất gì); phong phú', 'adjective', '[{"en":"He dreamed of becoming rich and buying a big house.","vi":"Anh ấy mơ trở nên giàu có và mua một ngôi nhà lớn."},{"en":"Oranges and lemons are rich in vitamin C.","vi":"Cam và chanh giàu vitamin C."},{"en":"This city has a rich history and many old buildings.","vi":"Thành phố này có bề dày lịch sử và nhiều tòa nhà cổ."}]', '[{"phrase":"rich in"},{"phrase":"rich history"},{"phrase":"get rich"}]', NULL, '/rɪtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ric/rich_/rich__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 13, 'wind', 'gió', 'noun', '[{"en":"The wind blew the leaves across the yard.","vi":"Gió thổi lá bay khắp sân."},{"en":"The wind was so cold that we went back inside.","vi":"Gió lạnh đến mức chúng tôi phải quay vào trong."},{"en":"Strong winds are expected along the coast tonight.","vi":"Dự báo tối nay sẽ có gió mạnh dọc bờ biển."}]', '[{"phrase":"strong wind"},{"phrase":"cold wind"},{"phrase":"the wind blows"}]', 'wind (n) /wɪnd/ gió ≠ wind (v) /waɪnd/ quấn, lên dây', '/wɪnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/wind_/wind__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 14, 'none', 'không ai; không cái nào; không chút nào', 'pronoun', '[{"en":"I bought three cakes, but there are none left now.","vi":"Tôi đã mua ba cái bánh, nhưng giờ chẳng còn cái nào."},{"en":"None of my friends could come to the party.","vi":"Không ai trong số bạn bè tôi đến dự bữa tiệc được."},{"en":"We needed more milk, but the shop had none.","vi":"Chúng tôi cần thêm sữa, nhưng cửa hàng lại hết sạch."}]', '[{"phrase":"none of"},{"phrase":"none left"},{"phrase":"none at all"}]', 'none of + danh từ số nhiều / không đếm được', '/nʌn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/non/none_/none__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 15, 'exchange', 'trao đổi; đổi (tiền, hàng)', 'verb', '[{"en":"We exchanged phone numbers before leaving the party.","vi":"Chúng tôi trao đổi số điện thoại trước khi rời bữa tiệc."},{"en":"Can I exchange this shirt for a smaller size?","vi":"Tôi có thể đổi chiếc áo này lấy cỡ nhỏ hơn không?"},{"en":"You can exchange money at the airport, but the rate is poor.","vi":"Bạn có thể đổi tiền ở sân bay, nhưng tỷ giá không tốt."}]', '[{"phrase":"exchange money"},{"phrase":"exchange ideas"},{"phrase":"exchange information"},{"phrase":"exchange gifts"}]', 'exchange A for B: đổi A lấy B', '/ɪksˈtʃeɪndʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excha/exchange__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 16, 'budget', 'ngân sách', 'noun', '[{"en":"We''re planning a trip on a tight budget this summer.","vi":"Hè này chúng tôi dự định đi du lịch với ngân sách eo hẹp."},{"en":"The project went over budget by twenty percent.","vi":"Dự án đã vượt ngân sách hai mươi phần trăm."},{"en":"Our school has a small budget for new books.","vi":"Trường chúng tôi có một khoản ngân sách nhỏ để mua sách mới."}]', '[{"phrase":"tight budget"},{"phrase":"over budget"},{"phrase":"on a budget"},{"phrase":"budget for"}]', NULL, '/ˈbʌdʒɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bud/budge/budget__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 17, 'famous', 'nổi tiếng', 'adjective', '[{"en":"This town is famous for its fresh seafood.","vi":"Thị trấn này nổi tiếng với hải sản tươi ngon."},{"en":"She wants to become a famous singer one day.","vi":"Cô ấy muốn một ngày nào đó trở thành ca sĩ nổi tiếng."},{"en":"We visited the famous bridge on our first day in the city.","vi":"Chúng tôi đã tham quan cây cầu nổi tiếng vào ngày đầu tiên ở thành phố."}]', '[{"phrase":"famous for"},{"phrase":"world-famous"},{"phrase":"become famous"}]', 'famous for sth: nổi tiếng về cái gì', '/ˈfeɪməs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fam/famou/famous__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 18, 'blood', 'máu', 'noun', '[{"en":"I have to go for a blood test tomorrow morning.","vi":"Sáng mai tôi phải đi xét nghiệm máu."},{"en":"Regular exercise can help lower your blood pressure.","vi":"Tập thể dục đều đặn có thể giúp giảm huyết áp."},{"en":"Hospitals always need more people to give blood.","vi":"Các bệnh viện luôn cần thêm người hiến máu."}]', '[{"phrase":"blood test"},{"phrase":"blood pressure"},{"phrase":"give blood"},{"phrase":"blood type"}]', 'không đếm được', '/blʌd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/blo/blood/blood__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 19, 'appropriate', 'phù hợp; thích hợp', 'adjective', '[{"en":"Jeans are not appropriate for a job interview.","vi":"Quần jeans không phù hợp để mặc đi phỏng vấn xin việc."},{"en":"Please wait for an appropriate time to ask questions.","vi":"Vui lòng chờ thời điểm thích hợp để đặt câu hỏi."},{"en":"Is this movie appropriate for young children?","vi":"Bộ phim này có phù hợp với trẻ nhỏ không?"}]', '[{"phrase":"appropriate for"},{"phrase":"appropriate time"},{"phrase":"appropriate action"}]', 'trái nghĩa: inappropriate', '/əˈprəʊpriət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appro/appropriate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 20, 'block', 'khối; tòa nhà; dãy nhà (giữa hai con phố)', 'noun', '[{"en":"The post office is two blocks from here.","vi":"Bưu điện cách đây hai dãy nhà."},{"en":"They live in a tall apartment block near the river.","vi":"Họ sống trong một tòa chung cư cao tầng gần bờ sông."},{"en":"The children built a tower with wooden blocks.","vi":"Bọn trẻ xếp một tòa tháp bằng những khối gỗ."}]', '[{"phrase":"apartment block"},{"phrase":"around the block"},{"phrase":"block of ice"}]', NULL, '/blɑːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/blo/block/block__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 21, 'warm', 'ấm; ấm áp; nồng nhiệt', 'adjective', '[{"en":"Wear a warm coat because it''s cold outside.","vi":"Hãy mặc áo khoác ấm vì ngoài trời lạnh."},{"en":"The weather is warm enough to swim today.","vi":"Hôm nay thời tiết đủ ấm để đi bơi."},{"en":"Our hosts gave us a very warm welcome.","vi":"Chủ nhà đã chào đón chúng tôi rất nồng nhiệt."}]', '[{"phrase":"warm weather"},{"phrase":"warm welcome"},{"phrase":"warm clothes"},{"phrase":"keep warm"}]', NULL, '/wɔːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/war/warm_/warm__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 22, 'count', 'đếm; tính; có giá trị, quan trọng', 'verb', '[{"en":"My little son can already count to one hundred.","vi":"Con trai nhỏ của tôi đã biết đếm đến một trăm."},{"en":"She counted the money twice before paying.","vi":"Cô ấy đếm tiền hai lần trước khi trả."},{"en":"Every minute counts when you''re running late for a flight.","vi":"Từng phút đều quan trọng khi bạn sắp trễ chuyến bay."}]', '[{"phrase":"count to ten"},{"phrase":"count money"},{"phrase":"count on"},{"phrase":"every minute counts"}]', 'count on sb: trông cậy vào ai', '/kaʊnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/count/count__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 23, 'scene', 'cảnh (phim, kịch); hiện trường; khung cảnh', 'noun', '[{"en":"My favorite scene in the movie is at the very end.","vi":"Cảnh tôi thích nhất trong phim nằm ở ngay cuối."},{"en":"The police arrived at the scene within minutes.","vi":"Cảnh sát đã đến hiện trường chỉ trong vài phút."},{"en":"We sat on the hill and enjoyed the peaceful scene below.","vi":"Chúng tôi ngồi trên đồi và ngắm khung cảnh yên bình bên dưới."}]', '[{"phrase":"at the scene"},{"phrase":"final scene"},{"phrase":"opening scene"},{"phrase":"behind the scenes"}]', NULL, '/siːn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sce/scene/scene__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 24, 'writer', 'nhà văn; người viết', 'noun', '[{"en":"She is a successful writer of children''s books.","vi":"Cô ấy là một nhà văn thành công chuyên viết sách thiếu nhi."},{"en":"My brother wants to be a writer when he grows up.","vi":"Em trai tôi muốn trở thành nhà văn khi lớn lên."},{"en":"The writer of this article clearly knows a lot about cooking.","vi":"Người viết bài báo này rõ ràng rất am hiểu về nấu ăn."}]', '[{"phrase":"famous writer"},{"phrase":"successful writer"},{"phrase":"children''s writer"}]', NULL, '/ˈraɪtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wri/write/writer__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 25, 'content', 'nội dung', 'noun', '[{"en":"The content of the course is useful for beginners.","vi":"Nội dung khóa học hữu ích cho người mới bắt đầu."},{"en":"Parents should check the content of the games their kids play.","vi":"Cha mẹ nên kiểm tra nội dung các trò chơi mà con mình chơi."},{"en":"The company creates video content for social media.","vi":"Công ty sản xuất nội dung video cho mạng xã hội."}]', '[{"phrase":"the content of"},{"phrase":"online content"},{"phrase":"video content"}]', 'content (n) nội dung ≠ content (adj) hài lòng – khác trọng âm', '/ˈkɑːntent/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 26, 'prevent', 'ngăn chặn; phòng ngừa', 'verb', '[{"en":"Washing your hands often can prevent many illnesses.","vi":"Rửa tay thường xuyên có thể phòng ngừa nhiều bệnh."},{"en":"The heavy rain prevented us from going out.","vi":"Trận mưa lớn đã ngăn chúng tôi ra ngoài."},{"en":"They put up a fence to prevent the dog from escaping.","vi":"Họ dựng hàng rào để ngăn con chó chạy ra ngoài."}]', '[{"phrase":"prevent disease"},{"phrase":"prevent accidents"},{"phrase":"help prevent"}]', 'prevent sb/sth from doing sth', '/prɪˈvent/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/preve/prevent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 27, 'safe', 'an toàn', 'adjective', '[{"en":"Is it safe to swim in this river?","vi":"Bơi ở con sông này có an toàn không?"},{"en":"Keep your passport in a safe place.","vi":"Hãy cất hộ chiếu ở nơi an toàn."},{"en":"The children came home safe and sound after the long trip.","vi":"Bọn trẻ đã về nhà bình an vô sự sau chuyến đi dài."}]', '[{"phrase":"safe place"},{"phrase":"safe and sound"},{"phrase":"feel safe"},{"phrase":"safe from"}]', NULL, '/seɪf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/saf/safe_/safe__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 28, 'invite', 'mời', 'verb', '[{"en":"They invited us to their wedding in June.","vi":"Họ mời chúng tôi đến dự đám cưới của họ vào tháng Sáu."},{"en":"I''d like to invite you to dinner on Saturday.","vi":"Tôi muốn mời bạn đi ăn tối vào thứ Bảy."},{"en":"Visitors are invited to leave their comments in the book.","vi":"Khách tham quan được mời để lại cảm nghĩ trong cuốn sổ."}]', '[{"phrase":"invite someone to dinner"},{"phrase":"invite guests"},{"phrase":"invite friends"}]', 'invite sb to sth / to do sth', '/ɪnˈvaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/invit/invite__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 29, 'mix', 'trộn; pha; hòa lẫn', 'verb', '[{"en":"Mix the flour and sugar together in a large bowl.","vi":"Trộn đều bột mì và đường trong một cái tô lớn."},{"en":"You can''t mix oil and water, no matter how hard you try.","vi":"Bạn không thể hòa dầu với nước, dù có cố gắng đến đâu."},{"en":"She mixed blue and yellow paint to make green.","vi":"Cô ấy pha sơn xanh dương với vàng để tạo ra màu xanh lá."}]', '[{"phrase":"mix together"},{"phrase":"mix with"},{"phrase":"mix well"}]', NULL, '/mɪks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mix/mix__/mix__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-01', 30, 'element', 'yếu tố; thành phần; nguyên tố (hóa học)', 'noun', '[{"en":"Trust is an important element in any relationship.","vi":"Sự tin tưởng là yếu tố quan trọng trong mọi mối quan hệ."},{"en":"Humor is a key element of his teaching style.","vi":"Sự hài hước là yếu tố then chốt trong phong cách giảng dạy của anh ấy."},{"en":"Oxygen is one of the most common elements on Earth.","vi":"Oxy là một trong những nguyên tố phổ biến nhất trên Trái Đất."}]', '[{"phrase":"key element"},{"phrase":"important element"},{"phrase":"chemical element"}]', NULL, '/ˈelɪmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ele/eleme/element__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-03', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 3', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 3);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 1, 'expensive', 'đắt; đắt tiền', 'adjective', '[{"en":"This restaurant is nice, but the food is too expensive for us.","vi":"Nhà hàng này đẹp nhưng đồ ăn quá đắt đối với chúng tôi."},{"en":"She bought an expensive watch for her father''s birthday.","vi":"Cô ấy đã mua một chiếc đồng hồ đắt tiền nhân dịp sinh nhật bố."},{"en":"Living in a big city can be very expensive.","vi":"Sống ở thành phố lớn có thể rất tốn kém."}]', '[{"phrase":"very expensive"},{"phrase":"too expensive"},{"phrase":"expensive car"}]', 'expensive ≠ cheap (rẻ)', '/ɪkˈspensɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/expen/expensive__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 2, 'sample', 'mẫu; mẫu thử', 'noun', '[{"en":"The nurse took a blood sample from my arm.","vi":"Y tá đã lấy mẫu máu từ cánh tay tôi."},{"en":"The shop was giving out free samples of cheese.","vi":"Cửa hàng đang phát các mẫu phô mai dùng thử miễn phí."},{"en":"Could you send us a sample of your work?","vi":"Bạn có thể gửi cho chúng tôi một mẫu sản phẩm bạn đã làm không?"}]', '[{"phrase":"blood sample"},{"phrase":"free sample"},{"phrase":"take a sample"}]', NULL, '/ˈsæmpl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sam/sampl/sample__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 3, 'sex', 'giới tính', 'noun', '[{"en":"Please write your name, age and sex on the form.","vi":"Vui lòng ghi tên, tuổi và giới tính vào tờ đơn."},{"en":"They decided not to find out the sex of their baby.","vi":"Họ quyết định không tìm hiểu giới tính của em bé."},{"en":"The survey asked people about their age, sex and income.","vi":"Cuộc khảo sát hỏi mọi người về tuổi, giới tính và thu nhập."}]', '[{"phrase":"the opposite sex"},{"phrase":"age and sex"},{"phrase":"both sexes"}]', NULL, '/seks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sex/sex__/sex__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 4, 'deliver', 'giao (hàng); phát biểu, trình bày', 'verb', '[{"en":"The store will deliver your new sofa on Friday morning.","vi":"Cửa hàng sẽ giao chiếc ghế sofa mới cho bạn vào sáng thứ Sáu."},{"en":"Our pizza was delivered in less than thirty minutes.","vi":"Pizza của chúng tôi được giao chưa đến ba mươi phút."},{"en":"She delivered a short speech at her sister''s wedding.","vi":"Cô ấy đã phát biểu ngắn tại đám cưới của chị gái."}]', '[{"phrase":"deliver a package"},{"phrase":"deliver a speech"},{"phrase":"deliver mail"}]', NULL, '/dɪˈlɪvər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/del/deliv/deliver__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 5, 'video', 'video; đoạn phim', 'noun', '[{"en":"My son spends hours watching funny videos online.","vi":"Con trai tôi dành hàng giờ xem video hài trên mạng."},{"en":"Did you make a video of the concert last night?","vi":"Tối qua bạn có quay video buổi hòa nhạc không?"},{"en":"We had a video call with our grandparents on Sunday.","vi":"Chúng tôi đã gọi video với ông bà vào Chủ nhật."}]', '[{"phrase":"watch a video"},{"phrase":"video call"},{"phrase":"make a video"},{"phrase":"music video"}]', NULL, '/ˈvɪdiəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vid/video/video__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 6, 'connection', 'sự kết nối; mối liên hệ; chuyến nối tiếp', 'noun', '[{"en":"The internet connection in this hotel is really slow.","vi":"Kết nối internet ở khách sạn này thật sự rất chậm."},{"en":"Police found no connection between the two cases.","vi":"Cảnh sát không tìm thấy mối liên hệ nào giữa hai vụ việc."},{"en":"Our first flight was late, so we missed our connection.","vi":"Chuyến bay đầu tiên bị trễ nên chúng tôi lỡ chuyến bay nối tiếp."}]', '[{"phrase":"internet connection"},{"phrase":"connection between"},{"phrase":"in connection with"},{"phrase":"miss a connection"}]', NULL, '/kəˈnekʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconn/xconnection__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 7, 'primary', 'chính, chủ yếu; (thuộc) tiểu học', 'adjective', '[{"en":"Our primary goal this year is to save money for a house.","vi":"Mục tiêu chính của chúng tôi năm nay là tiết kiệm tiền mua nhà."},{"en":"Safety is the primary concern when children play outside.","vi":"An toàn là mối quan tâm hàng đầu khi trẻ em chơi bên ngoài."},{"en":"My mother has taught at a primary school for twenty years.","vi":"Mẹ tôi đã dạy ở một trường tiểu học được hai mươi năm."}]', '[{"phrase":"primary school"},{"phrase":"primary goal"},{"phrase":"primary reason"},{"phrase":"primary concern"}]', NULL, '/ˈpraɪmeri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/prima/primary__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 8, 'weather', 'thời tiết', 'noun', '[{"en":"The weather was perfect for a picnic in the park.","vi":"Thời tiết thật lý tưởng cho một buổi dã ngoại trong công viên."},{"en":"What will the weather be like tomorrow?","vi":"Thời tiết ngày mai sẽ thế nào?"},{"en":"Our flight was canceled because of bad weather.","vi":"Chuyến bay của chúng tôi bị hủy vì thời tiết xấu."}]', '[{"phrase":"bad weather"},{"phrase":"weather forecast"},{"phrase":"hot weather"},{"phrase":"cold weather"}]', 'không đếm được; weather ≠ whether (liệu)', '/ˈweðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wea/weath/weather__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 9, 'collect', 'thu thập, sưu tầm; đón; lấy (đồ)', 'verb', '[{"en":"My brother has collected old coins since he was ten.","vi":"Anh trai tôi sưu tầm tiền xu cổ từ năm mười tuổi."},{"en":"Can you collect the kids from school today?","vi":"Hôm nay bạn đón bọn trẻ ở trường được không?"},{"en":"The researchers collected data from over five hundred students.","vi":"Các nhà nghiên cứu đã thu thập dữ liệu từ hơn năm trăm sinh viên."}]', '[{"phrase":"collect data"},{"phrase":"collect money"},{"phrase":"collect stamps"},{"phrase":"collect the children"}]', NULL, '/kəˈlekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colle/collect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 10, 'inform', 'thông báo, báo cho biết', 'verb', '[{"en":"Please inform your manager if you will be late.","vi":"Vui lòng báo cho quản lý biết nếu bạn sẽ đến muộn."},{"en":"We were informed that the meeting had been canceled.","vi":"Chúng tôi được thông báo rằng cuộc họp đã bị hủy."},{"en":"The school will inform parents of any changes by email.","vi":"Nhà trường sẽ thông báo cho phụ huynh mọi thay đổi qua email."}]', '[{"phrase":"inform somebody of"},{"phrase":"keep somebody informed"},{"phrase":"inform the police"}]', 'inform somebody of/about something', '/ɪnˈfɔːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inf/infor/inform__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 11, 'principle', 'nguyên tắc; nguyên lý', 'noun', '[{"en":"Honesty is an important principle in our family.","vi":"Trung thực là một nguyên tắc quan trọng trong gia đình chúng tôi."},{"en":"I agree with your plan in principle, but it costs too much.","vi":"Về nguyên tắc tôi đồng ý với kế hoạch của bạn, nhưng nó quá tốn kém."},{"en":"The students learned the basic principles of physics this term.","vi":"Học kỳ này, học sinh đã học các nguyên lý cơ bản của vật lý."}]', '[{"phrase":"basic principle"},{"phrase":"in principle"},{"phrase":"a matter of principle"}]', 'principle (nguyên tắc) ≠ principal (hiệu trưởng; chính)', '/ˈprɪnsəpl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/princ/principle__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 12, 'straight', 'thẳng; ngay, trực tiếp', 'adverb', '[{"en":"Go straight ahead and turn left at the bank.","vi":"Đi thẳng về phía trước rồi rẽ trái ở ngân hàng."},{"en":"I was so tired that I went straight to bed.","vi":"Tôi mệt đến mức đi ngủ ngay."},{"en":"Please stand up straight and look at the camera.","vi":"Vui lòng đứng thẳng lên và nhìn vào máy ảnh."}]', '[{"phrase":"straight ahead"},{"phrase":"go straight"},{"phrase":"straight away"},{"phrase":"sit up straight"}]', NULL, '/streɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/strai/straight__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 13, 'appeal', 'lời kêu gọi; sức hấp dẫn; kháng cáo', 'noun', '[{"en":"The hospital made an appeal for more blood donors.","vi":"Bệnh viện đã kêu gọi thêm người hiến máu."},{"en":"I don''t understand the appeal of watching golf on TV.","vi":"Tôi không hiểu sức hấp dẫn của việc xem đánh golf trên TV."},{"en":"The company lost its appeal and had to pay the fine.","vi":"Công ty đã thua kháng cáo và phải nộp tiền phạt."}]', '[{"phrase":"make an appeal"},{"phrase":"appeal for"},{"phrase":"wide appeal"},{"phrase":"lose an appeal"}]', NULL, '/əˈpiːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/app/appea/appeal__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 14, 'highly', 'rất, hết sức; đánh giá cao', 'adverb', '[{"en":"It is highly unlikely that it will snow in April.","vi":"Rất khó có khả năng trời sẽ có tuyết vào tháng Tư."},{"en":"I highly recommend the soup at this restaurant.","vi":"Tôi rất khuyên bạn nên thử món súp ở nhà hàng này."},{"en":"Her boss thinks highly of her work.","vi":"Sếp của cô ấy đánh giá cao công việc của cô ấy."}]', '[{"phrase":"highly recommend"},{"phrase":"highly unlikely"},{"phrase":"think highly of"},{"phrase":"highly skilled"}]', 'highly ≠ high (cao về độ cao)', '/ˈhaɪli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hig/highl/highly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 15, 'trust', 'tin tưởng, tin cậy', 'verb', '[{"en":"You can trust him to keep a secret.","vi":"Bạn có thể tin tưởng anh ấy sẽ giữ bí mật."},{"en":"I don''t trust the weather forecast in the mountains.","vi":"Tôi không tin vào dự báo thời tiết ở vùng núi."},{"en":"She has always trusted her parents'' advice.","vi":"Cô ấy luôn tin tưởng lời khuyên của bố mẹ."}]', '[{"phrase":"trust somebody"},{"phrase":"trust your instincts"},{"phrase":"completely trust"}]', NULL, '/trʌst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tru/trust/trust__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 16, 'wonderful', 'tuyệt vời', 'adjective', '[{"en":"Thank you for a wonderful evening, we really enjoyed it.","vi":"Cảm ơn bạn vì một buổi tối tuyệt vời, chúng tôi thật sự rất vui."},{"en":"The view from the top of the hill is wonderful.","vi":"Quang cảnh từ đỉnh đồi thật tuyệt vời."},{"en":"It''s wonderful to see you again after so many years.","vi":"Thật tuyệt khi được gặp lại bạn sau ngần ấy năm."}]', '[{"phrase":"wonderful time"},{"phrase":"wonderful news"},{"phrase":"absolutely wonderful"}]', NULL, '/ˈwʌndərfl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/won/wonde/wonderful__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 17, 'flat', 'căn hộ; bằng phẳng; (lốp) xịt', 'noun', '[{"en":"They rent a small flat near the city center.","vi":"Họ thuê một căn hộ nhỏ gần trung tâm thành phố."},{"en":"This part of the country is very flat, so it''s good for cycling.","vi":"Vùng này của đất nước rất bằng phẳng nên rất hợp để đạp xe."},{"en":"We were late because our car had a flat tire.","vi":"Chúng tôi đến muộn vì xe bị xịt lốp."}]', '[{"phrase":"rent a flat"},{"phrase":"flat surface"},{"phrase":"flat tire"}]', 'flat (Anh) = apartment (Mỹ)', '/flæt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fla/flat_/flat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 18, 'absolutely', 'hoàn toàn; tuyệt đối; cực kỳ', 'adverb', '[{"en":"You''re absolutely right, I should have called first.","vi":"Bạn hoàn toàn đúng, lẽ ra tôi nên gọi điện trước."},{"en":"There is absolutely nothing to eat in the fridge.","vi":"Trong tủ lạnh chẳng có gì để ăn cả."},{"en":"I absolutely love the new café on our street.","vi":"Tôi cực kỳ thích quán cà phê mới trên phố nhà mình."}]', '[{"phrase":"absolutely right"},{"phrase":"absolutely nothing"},{"phrase":"absolutely sure"},{"phrase":"absolutely delicious"}]', NULL, '/ˈæbsəluːtli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abs/absol/absolutely__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 19, 'flow', 'dòng chảy; luồng (giao thông, thông tin)', 'noun', '[{"en":"The police officer was directing the flow of traffic.","vi":"Viên cảnh sát đang điều khiển luồng giao thông."},{"en":"Regular exercise improves the flow of blood to the brain.","vi":"Tập thể dục đều đặn giúp cải thiện lưu lượng máu lên não."},{"en":"Heavy rain increased the flow of water in the river.","vi":"Mưa lớn làm tăng dòng chảy của nước trên sông."}]', '[{"phrase":"flow of traffic"},{"phrase":"blood flow"},{"phrase":"flow of information"},{"phrase":"cash flow"}]', NULL, '/fləʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/flo/flow_/flow__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 20, 'fair', 'công bằng; hợp lý; (tóc) vàng hoe, (da) sáng', 'adjective', '[{"en":"It''s not fair that I always have to wash the dishes.","vi":"Thật không công bằng khi lúc nào tôi cũng phải rửa bát."},{"en":"I think fifty dollars is a fair price for this bike.","vi":"Tôi nghĩ năm mươi đô la là giá hợp lý cho chiếc xe đạp này."},{"en":"The baby has fair hair and blue eyes.","vi":"Em bé có mái tóc vàng hoe và đôi mắt xanh."}]', '[{"phrase":"fair price"},{"phrase":"fair share"},{"phrase":"fair hair"},{"phrase":"not fair"}]', NULL, '/fer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fai/fair_/fair__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 21, 'additional', 'thêm, bổ sung', 'adjective', '[{"en":"There is an additional charge for extra luggage.","vi":"Có tính phí bổ sung cho hành lý quá cước."},{"en":"Please contact us if you need any additional information.","vi":"Vui lòng liên hệ với chúng tôi nếu bạn cần thêm thông tin."},{"en":"The school hired two additional teachers this year.","vi":"Năm nay trường đã tuyển thêm hai giáo viên."}]', '[{"phrase":"additional information"},{"phrase":"additional cost"},{"phrase":"additional charge"}]', NULL, '/əˈdɪʃənl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/add/addit/additional__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 22, 'responsible', 'chịu trách nhiệm; có trách nhiệm', 'adjective', '[{"en":"Who is responsible for cleaning the kitchen this week?","vi":"Tuần này ai chịu trách nhiệm dọn dẹp nhà bếp?"},{"en":"Parents are responsible for their children''s safety.","vi":"Cha mẹ chịu trách nhiệm về sự an toàn của con cái."},{"en":"She is a very responsible young woman.","vi":"Cô ấy là một cô gái trẻ rất có trách nhiệm."}]', '[{"phrase":"responsible for"},{"phrase":"hold somebody responsible"},{"phrase":"feel responsible"}]', 'responsible for something', '/rɪˈspɑːnsəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respo/responsible__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 23, 'farm', 'nông trại, trang trại', 'noun', '[{"en":"My grandparents live on a farm in the countryside.","vi":"Ông bà tôi sống ở một trang trại ở nông thôn."},{"en":"The children fed the animals when they visited the farm.","vi":"Bọn trẻ đã cho các con vật ăn khi đến thăm trang trại."},{"en":"He has worked on a dairy farm since he left school.","vi":"Anh ấy làm việc ở một trang trại bò sữa từ khi rời ghế nhà trường."}]', '[{"phrase":"on a farm"},{"phrase":"farm animals"},{"phrase":"dairy farm"},{"phrase":"work on a farm"}]', 'sống/làm việc on a farm', '/fɑːrm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/far/farm_/farm__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 24, 'collection', 'bộ sưu tập; sự thu gom', 'noun', '[{"en":"My uncle has a huge collection of old records.","vi":"Chú tôi có một bộ sưu tập đĩa nhạc cũ rất lớn."},{"en":"The museum''s collection includes many paintings from Asia.","vi":"Bộ sưu tập của bảo tàng có nhiều bức tranh từ châu Á."},{"en":"Garbage collection on our street is on Tuesdays.","vi":"Việc thu gom rác ở phố chúng tôi diễn ra vào thứ Ba."}]', '[{"phrase":"a collection of"},{"phrase":"large collection"},{"phrase":"art collection"},{"phrase":"garbage collection"}]', NULL, '/kəˈlekʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/col/colle/collection__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 25, 'hang', 'treo; móc', 'verb', '[{"en":"Can you help me hang this picture on the wall?","vi":"Bạn có thể giúp tôi treo bức tranh này lên tường không?"},{"en":"She hung her coat behind the door.","vi":"Cô ấy móc áo khoác sau cánh cửa."},{"en":"Colorful lights were hanging from the trees in the garden.","vi":"Những chiếc đèn nhiều màu được treo trên cây trong vườn."}]', '[{"phrase":"hang a picture"},{"phrase":"hang on the wall"},{"phrase":"hang up"},{"phrase":"hang out"}]', 'hang – hung – hung', '/hæŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/han/hang_/hang__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 26, 'negative', 'tiêu cực; phủ định; âm tính', 'adjective', '[{"en":"Too much screen time can have a negative effect on sleep.","vi":"Dùng màn hình quá nhiều có thể ảnh hưởng tiêu cực đến giấc ngủ."},{"en":"Try not to be so negative about your new job.","vi":"Cố gắng đừng quá tiêu cực về công việc mới của bạn."},{"en":"The good news is that the test results were negative.","vi":"Tin tốt là kết quả xét nghiệm âm tính."}]', '[{"phrase":"negative effect"},{"phrase":"negative impact"},{"phrase":"negative attitude"},{"phrase":"test negative"}]', 'negative ≠ positive (tích cực; dương tính)', '/ˈneɡətɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/neg/negat/negative__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 27, 'band', 'ban nhạc; dải, băng', 'noun', '[{"en":"My brother plays the drums in a rock band.","vi":"Anh trai tôi chơi trống trong một ban nhạc rock."},{"en":"A local band played at their wedding party.","vi":"Một ban nhạc địa phương đã biểu diễn trong tiệc cưới của họ."},{"en":"She tied her hair back with a rubber band.","vi":"Cô ấy buộc tóc ra sau bằng một sợi dây thun."}]', '[{"phrase":"rock band"},{"phrase":"play in a band"},{"phrase":"join a band"},{"phrase":"rubber band"}]', NULL, '/bænd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/ban/band_/band__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 28, 'relative', 'họ hàng, người thân', 'noun', '[{"en":"We visit our relatives in the countryside every New Year.","vi":"Mỗi dịp Tết, chúng tôi về quê thăm họ hàng."},{"en":"Only close relatives were invited to the small wedding.","vi":"Chỉ những người thân trong gia đình được mời đến đám cưới nhỏ."},{"en":"She is staying with a relative while she studies abroad.","vi":"Cô ấy đang ở nhà một người họ hàng trong thời gian du học."}]', '[{"phrase":"close relative"},{"phrase":"distant relative"},{"phrase":"friends and relatives"},{"phrase":"visit relatives"}]', NULL, '/ˈrelətɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relat/relative__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 29, 'tour', 'chuyến tham quan, chuyến du lịch; chuyến lưu diễn', 'noun', '[{"en":"We took a guided tour of the old town.","vi":"Chúng tôi đã tham gia một chuyến tham quan phố cổ có hướng dẫn viên."},{"en":"The tour of the factory lasted about two hours.","vi":"Chuyến tham quan nhà máy kéo dài khoảng hai tiếng."},{"en":"The band is going on a world tour next year.","vi":"Ban nhạc sẽ đi lưu diễn vòng quanh thế giới vào năm tới."}]', '[{"phrase":"guided tour"},{"phrase":"go on tour"},{"phrase":"world tour"},{"phrase":"tour guide"}]', NULL, '/tʊr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tou/tour_/tour__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-03', 30, 'alternative', 'sự lựa chọn khác, phương án thay thế', 'noun', '[{"en":"The road is closed, so we need to find an alternative.","vi":"Con đường bị chặn nên chúng tôi cần tìm một phương án khác."},{"en":"Walking is a healthy alternative to driving to work.","vi":"Đi bộ là một lựa chọn lành mạnh thay cho việc lái xe đi làm."},{"en":"We had no alternative but to wait for the next train.","vi":"Chúng tôi không còn cách nào khác ngoài việc chờ chuyến tàu tiếp theo."}]', '[{"phrase":"alternative to"},{"phrase":"no alternative"},{"phrase":"a good alternative"},{"phrase":"cheaper alternative"}]', 'an alternative to something', '/ɔːlˈtɜːrnətɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alt/alter/alternative__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-04', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 4', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 4);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 1, 'software', 'phần mềm', 'noun', '[{"en":"You need to install the new software before the meeting.","vi":"Bạn cần cài đặt phần mềm mới trước cuộc họp."},{"en":"My brother writes software for a small company in the city.","vi":"Anh trai tôi viết phần mềm cho một công ty nhỏ trong thành phố."},{"en":"Is this software free, or do we have to pay for it?","vi":"Phần mềm này miễn phí hay chúng ta phải trả tiền?"}]', '[{"phrase":"install software"},{"phrase":"software company"},{"phrase":"computer software"},{"phrase":"update the software"}]', 'không đếm được', '/ˈsɔːftwer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sof/softw/software__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 2, 'pair', 'đôi; cặp', 'noun', '[{"en":"I bought a new pair of shoes for the wedding.","vi":"Tôi đã mua một đôi giày mới để đi dự đám cưới."},{"en":"The teacher asked us to work in pairs today.","vi":"Hôm nay giáo viên yêu cầu chúng tôi làm việc theo cặp."},{"en":"Can I borrow a pair of scissors from you?","vi":"Tôi có thể mượn bạn một cái kéo không?"}]', '[{"phrase":"a pair of shoes"},{"phrase":"a pair of glasses"},{"phrase":"work in pairs"}]', NULL, '/per/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pai/pair_/pair__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 3, 'ship', 'tàu thủy; con tàu', 'noun', '[{"en":"We watched the big ship leave the port at sunset.","vi":"Chúng tôi nhìn con tàu lớn rời cảng lúc hoàng hôn."},{"en":"My grandfather worked on a cargo ship for twenty years.","vi":"Ông tôi đã làm việc trên một tàu chở hàng suốt hai mươi năm."},{"en":"They crossed the ocean by ship instead of flying.","vi":"Họ vượt đại dương bằng tàu thủy thay vì đi máy bay."}]', '[{"phrase":"by ship"},{"phrase":"cargo ship"},{"phrase":"cruise ship"}]', NULL, '/ʃɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/shi/ship_/ship__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 4, 'attitude', 'thái độ; quan điểm', 'noun', '[{"en":"She always has a positive attitude, even on bad days.","vi":"Cô ấy luôn có thái độ tích cực, kể cả vào những ngày tồi tệ."},{"en":"His attitude toward work has changed a lot this year.","vi":"Năm nay thái độ của anh ấy đối với công việc đã thay đổi nhiều."},{"en":"Young people''s attitudes to marriage are different from their parents''.","vi":"Quan điểm của giới trẻ về hôn nhân khác với cha mẹ họ."}]', '[{"phrase":"positive attitude"},{"phrase":"attitude toward"},{"phrase":"change your attitude"},{"phrase":"bad attitude"}]', 'attitude to/toward(s) something', '/ˈætɪtuːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/attit/attitude__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 5, 'cheap', 'rẻ; kém chất lượng', 'adjective', '[{"en":"The food at this little restaurant is cheap and delicious.","vi":"Đồ ăn ở nhà hàng nhỏ này rẻ mà ngon."},{"en":"We found a cheap hotel near the train station.","vi":"Chúng tôi tìm được một khách sạn giá rẻ gần ga tàu."},{"en":"These cheap headphones broke after only two weeks.","vi":"Cái tai nghe rẻ tiền này hỏng chỉ sau hai tuần."}]', '[{"phrase":"cheap hotel"},{"phrase":"relatively cheap"},{"phrase":"cheap flights"}]', NULL, '/tʃiːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/che/cheap/cheap__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 6, 'double', 'gấp đôi; đôi', 'adjective', '[{"en":"I''d like to book a double room for three nights.","vi":"Tôi muốn đặt một phòng đôi trong ba đêm."},{"en":"Rent in the city center is almost double what we pay now.","vi":"Tiền thuê nhà ở trung tâm thành phố gần gấp đôi số chúng tôi đang trả."},{"en":"He ordered a double espresso to stay awake.","vi":"Anh ấy gọi một ly espresso đúp để giữ tỉnh táo."}]', '[{"phrase":"double room"},{"phrase":"double bed"},{"phrase":"double the price"}]', NULL, '/ˈdʌbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dou/doubl/double__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 7, 'leg', 'chân; chặng', 'noun', '[{"en":"He broke his leg while playing soccer last winter.","vi":"Anh ấy bị gãy chân khi chơi bóng đá vào mùa đông năm ngoái."},{"en":"My legs were tired after walking around the city all day.","vi":"Chân tôi mỏi nhừ sau khi đi bộ quanh thành phố cả ngày."},{"en":"The first leg of our trip was a long train ride.","vi":"Chặng đầu tiên của chuyến đi là một chuyến tàu dài."}]', '[{"phrase":"broken leg"},{"phrase":"break your leg"},{"phrase":"long legs"},{"phrase":"first leg"}]', NULL, '/leɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/leg/leg__/leg__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 8, 'observe', 'quan sát; tuân thủ', 'verb', '[{"en":"The children observed the birds through a small window.","vi":"Bọn trẻ quan sát những con chim qua một ô cửa sổ nhỏ."},{"en":"Scientists observed the animals closely for several months.","vi":"Các nhà khoa học đã quan sát kỹ những con vật trong vài tháng."},{"en":"All drivers must observe the speed limit near schools.","vi":"Mọi tài xế phải tuân thủ giới hạn tốc độ gần trường học."}]', '[{"phrase":"observe closely"},{"phrase":"carefully observe"},{"phrase":"observe the rules"}]', NULL, '/əbˈzɜːrv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obs/obser/observe__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 9, 'sentence', 'câu; bản án', 'noun', '[{"en":"Please write a sentence using each new word.","vi":"Hãy viết một câu với mỗi từ mới."},{"en":"I didn''t understand the last sentence of the email.","vi":"Tôi không hiểu câu cuối cùng của email."},{"en":"The judge gave him a sentence of three years.","vi":"Thẩm phán tuyên cho anh ta bản án ba năm tù."}]', '[{"phrase":"write a sentence"},{"phrase":"complete sentence"},{"phrase":"prison sentence"}]', NULL, '/ˈsentəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sen/sente/sentence__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 10, 'print', 'in; in ra', 'verb', '[{"en":"Could you print two copies of this report for me?","vi":"Bạn có thể in giúp tôi hai bản báo cáo này không?"},{"en":"I printed my boarding pass before leaving for the airport.","vi":"Tôi đã in thẻ lên máy bay trước khi ra sân bay."},{"en":"The printer in our office can''t print in color.","vi":"Máy in ở văn phòng chúng tôi không in màu được."}]', '[{"phrase":"print a copy"},{"phrase":"print out"},{"phrase":"print in color"}]', 'print out = in ra', '/prɪnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/print/print__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 11, 'progress', 'sự tiến bộ; tiến triển', 'noun', '[{"en":"You''ve made great progress with your English this year.","vi":"Năm nay bạn đã tiến bộ rất nhiều trong tiếng Anh."},{"en":"The manager wants a weekly update on our progress.","vi":"Quản lý muốn được cập nhật tiến độ của chúng tôi hằng tuần."},{"en":"There has been little progress in the talks so far.","vi":"Cho đến nay các cuộc đàm phán hầu như chưa có tiến triển."}]', '[{"phrase":"make progress"},{"phrase":"great progress"},{"phrase":"slow progress"}]', 'không đếm được', '/ˈprɑːɡres/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/progr/progress__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 12, 'truth', 'sự thật', 'noun', '[{"en":"Just tell me the truth, and I won''t be angry.","vi":"Cứ nói thật với tôi đi, tôi sẽ không giận đâu."},{"en":"Nobody knows the truth about what happened that night.","vi":"Không ai biết sự thật về những gì đã xảy ra đêm hôm đó."},{"en":"There is some truth in what your mother said.","vi":"Những gì mẹ bạn nói cũng có phần sự thật."}]', '[{"phrase":"tell the truth"},{"phrase":"the whole truth"},{"phrase":"find out the truth"}]', NULL, '/truːθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tru/truth/truth__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 13, 'nobody', 'không ai; không người nào', 'pronoun', '[{"en":"I knocked on the door, but nobody answered.","vi":"Tôi gõ cửa nhưng không ai trả lời."},{"en":"Nobody in my family can cook as well as my grandmother.","vi":"Không ai trong gia đình tôi nấu ăn ngon bằng bà tôi."},{"en":"There was nobody at the office when I arrived.","vi":"Lúc tôi đến thì văn phòng không có ai."}]', '[{"phrase":"nobody else"},{"phrase":"nobody knows"},{"phrase":"almost nobody"}]', 'Đi với động từ số ít: Nobody knows.', '/ˈnəʊbədi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nob/nobod/nobody__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 14, 'examine', 'kiểm tra; xem xét; khám (bệnh)', 'verb', '[{"en":"The doctor examined my throat and said it was nothing serious.","vi":"Bác sĩ khám họng cho tôi và nói không có gì nghiêm trọng."},{"en":"Please examine the contract carefully before you sign it.","vi":"Hãy xem xét hợp đồng thật kỹ trước khi ký."},{"en":"The mechanic examined the engine but couldn''t find the problem.","vi":"Thợ máy kiểm tra động cơ nhưng không tìm ra lỗi."}]', '[{"phrase":"examine carefully"},{"phrase":"examine a patient"},{"phrase":"closely examine"}]', NULL, '/ɪɡˈzæmɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exa/exami/examine__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 15, 'lay', 'đặt; đặt nằm; đẻ (trứng)', 'verb', '[{"en":"She laid the baby gently on the bed.","vi":"Cô ấy nhẹ nhàng đặt em bé nằm xuống giường."},{"en":"He laid his keys on the kitchen table and sat down.","vi":"Anh ấy đặt chùm chìa khóa lên bàn bếp rồi ngồi xuống."},{"en":"Our chickens lay about six eggs every morning.","vi":"Mấy con gà nhà chúng tôi đẻ khoảng sáu quả trứng mỗi sáng."}]', '[{"phrase":"lay eggs"},{"phrase":"lay the table"},{"phrase":"lay something down"}]', 'lay – laid – laid; khác lie – lay – lain (nằm)', '/leɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lay/lay__/lay__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 16, 'speed', 'tốc độ', 'noun', '[{"en":"The train travels at a speed of 300 kilometers an hour.","vi":"Đoàn tàu chạy với tốc độ 300 ki-lô-mét một giờ."},{"en":"Our internet speed is very slow in the evenings.","vi":"Tốc độ mạng nhà chúng tôi rất chậm vào buổi tối."},{"en":"He was driving at high speed when the police stopped him.","vi":"Anh ta đang lái xe với tốc độ cao thì bị cảnh sát chặn lại."}]', '[{"phrase":"high speed"},{"phrase":"at full speed"},{"phrase":"speed limit"},{"phrase":"internet speed"}]', NULL, '/spiːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spe/speed/speed__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 17, 'politics', 'chính trị', 'noun', '[{"en":"My father loves talking about politics at the dinner table.","vi":"Bố tôi rất thích bàn chuyện chính trị trong bữa ăn."},{"en":"She studied politics and economics at university.","vi":"Cô ấy học ngành chính trị và kinh tế ở đại học."},{"en":"I''ve never been very interested in politics.","vi":"Tôi chưa bao giờ quan tâm nhiều đến chính trị."}]', '[{"phrase":"interested in politics"},{"phrase":"talk about politics"},{"phrase":"local politics"},{"phrase":"office politics"}]', 'politics (n) chính trị · political (adj) · politician (n) chính trị gia', '/ˈpɑːlətɪks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pol/polit/politics__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 18, 'reply', 'trả lời; hồi âm', 'verb', '[{"en":"Sorry, I forgot to reply to your message yesterday.","vi":"Xin lỗi, hôm qua tôi quên trả lời tin nhắn của bạn."},{"en":"When I asked her name, she smiled but didn''t reply.","vi":"Khi tôi hỏi tên, cô ấy mỉm cười nhưng không trả lời."},{"en":"The company replied to my email within an hour.","vi":"Công ty đã hồi âm email của tôi trong vòng một giờ."}]', '[{"phrase":"reply to an email"},{"phrase":"reply to a message"},{"phrase":"reply quickly"}]', 'reply to something/somebody', '/rɪˈplaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/reply/reply__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 19, 'display', 'trưng bày; hiển thị', 'verb', '[{"en":"The shop displays its newest clothes in the front window.","vi":"Cửa hàng trưng bày quần áo mới nhất ở cửa kính phía trước."},{"en":"Old family photos were displayed on the living room wall.","vi":"Những tấm ảnh gia đình cũ được trưng bày trên tường phòng khách."},{"en":"The screen displays the time and the temperature.","vi":"Màn hình hiển thị giờ và nhiệt độ."}]', '[{"phrase":"display a message"},{"phrase":"proudly display"},{"phrase":"be displayed on the screen"}]', NULL, '/dɪˈspleɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/displ/display__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 20, 'transfer', 'chuyển; chuyển khoản; chuyển công tác', 'verb', '[{"en":"I''ll transfer the money to your account this afternoon.","vi":"Chiều nay tôi sẽ chuyển tiền vào tài khoản của bạn."},{"en":"He was transferred to our office in another city.","vi":"Anh ấy được chuyển công tác sang văn phòng của chúng tôi ở thành phố khác."},{"en":"How do I transfer photos from my phone to my laptop?","vi":"Làm sao để chuyển ảnh từ điện thoại sang máy tính xách tay?"}]', '[{"phrase":"transfer money"},{"phrase":"transfer files"},{"phrase":"transfer to another school"}]', 'transfer – transferred – transferred', '/trænsˈfɜːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transfer__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 21, 'perfect', 'hoàn hảo; lý tưởng', 'adjective', '[{"en":"Nobody is perfect, so don''t be too hard on yourself.","vi":"Không ai hoàn hảo cả, nên đừng quá khắt khe với bản thân."},{"en":"The weather was perfect for a picnic in the park.","vi":"Thời tiết thật lý tưởng cho một buổi dã ngoại trong công viên."},{"en":"Her English is almost perfect after living abroad for years.","vi":"Tiếng Anh của cô ấy gần như hoàn hảo sau nhiều năm sống ở nước ngoài."}]', '[{"phrase":"perfect for"},{"phrase":"almost perfect"},{"phrase":"perfect example"},{"phrase":"perfect timing"}]', NULL, '/ˈpɜːrfɪkt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/perfe/perfect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 22, 'slightly', 'hơi; một chút', 'adverb', '[{"en":"I feel slightly better than I did this morning.","vi":"Tôi thấy đỡ hơn một chút so với sáng nay."},{"en":"Prices are slightly higher at the shop near our house.","vi":"Giá ở cửa hàng gần nhà chúng tôi hơi cao hơn."},{"en":"The two jackets look the same, but this one is slightly bigger.","vi":"Hai chiếc áo khoác trông giống nhau, nhưng chiếc này hơi to hơn."}]', '[{"phrase":"slightly different"},{"phrase":"slightly higher"},{"phrase":"only slightly"}]', NULL, '/ˈslaɪtli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sli/sligh/slightly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 23, 'overall', 'tổng thể; chung; nhìn chung', 'adjective', '[{"en":"The overall cost of the trip was lower than we expected.","vi":"Tổng chi phí của chuyến đi thấp hơn chúng tôi dự tính."},{"en":"My overall impression of the new school was very good.","vi":"Ấn tượng chung của tôi về ngôi trường mới rất tốt."},{"en":"There were a few problems, but overall it was a great weekend.","vi":"Có vài trục trặc, nhưng nhìn chung đó là một cuối tuần tuyệt vời."}]', '[{"phrase":"overall cost"},{"phrase":"overall impression"},{"phrase":"overall result"}]', 'Cũng dùng như trạng từ: Overall, … (nhìn chung)', '/ˌəʊvərˈɔːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ove/overa/overall__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 24, 'intend', 'dự định; có ý định', 'verb', '[{"en":"I intend to finish this project before the end of the month.","vi":"Tôi dự định hoàn thành dự án này trước cuối tháng."},{"en":"Sorry, I didn''t intend to hurt your feelings.","vi":"Xin lỗi, tôi không có ý làm bạn tổn thương."},{"en":"How long do you intend to stay in the country?","vi":"Bạn dự định ở lại đất nước này bao lâu?"}]', '[{"phrase":"intend to do"},{"phrase":"fully intend"},{"phrase":"never intended"}]', 'intend to do something', '/ɪnˈtend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inten/intend__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 25, 'user', 'người dùng; người sử dụng', 'noun', '[{"en":"The new app already has more than a million users.","vi":"Ứng dụng mới đã có hơn một triệu người dùng."},{"en":"Please enter your user name and password to continue.","vi":"Vui lòng nhập tên người dùng và mật khẩu để tiếp tục."},{"en":"Many phone users complain that the battery runs out too quickly.","vi":"Nhiều người dùng điện thoại phàn nàn rằng pin hết quá nhanh."}]', '[{"phrase":"internet user"},{"phrase":"user name"},{"phrase":"new users"},{"phrase":"road users"}]', NULL, '/ˈjuːzər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/use/user_/user__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 26, 'respond', 'phản hồi; trả lời; phản ứng', 'verb', '[{"en":"The hotel responded to my complaint the very next day.","vi":"Khách sạn đã phản hồi lời phàn nàn của tôi ngay ngày hôm sau."},{"en":"I asked him a question, but he didn''t respond.","vi":"Tôi hỏi anh ấy một câu nhưng anh ấy không trả lời."},{"en":"How did your parents respond when you told them the news?","vi":"Bố mẹ bạn phản ứng thế nào khi bạn báo tin cho họ?"}]', '[{"phrase":"respond to"},{"phrase":"respond quickly"},{"phrase":"fail to respond"}]', 'respond to something', '/rɪˈspɑːnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/res/respo/respond__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 27, 'dinner', 'bữa tối', 'noun', '[{"en":"What are we having for dinner tonight?","vi":"Tối nay chúng ta ăn gì?"},{"en":"My family always eats dinner together at seven o''clock.","vi":"Gia đình tôi luôn ăn tối cùng nhau lúc bảy giờ."},{"en":"He invited his new colleagues to dinner at his place.","vi":"Anh ấy mời các đồng nghiệp mới đến nhà mình ăn tối."}]', '[{"phrase":"have dinner"},{"phrase":"cook dinner"},{"phrase":"for dinner"},{"phrase":"invite someone to dinner"}]', NULL, '/ˈdɪnər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/din/dinne/dinner__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 28, 'slow', 'chậm', 'adjective', '[{"en":"The bus was so slow that I was late for work.","vi":"Xe buýt chạy chậm đến mức tôi bị muộn giờ làm."},{"en":"My laptop has become really slow since the last update.","vi":"Máy tính xách tay của tôi trở nên rất chậm từ lần cập nhật gần nhất."},{"en":"Learning a new language is a slow process.","vi":"Học một ngôn ngữ mới là một quá trình chậm."}]', '[{"phrase":"slow progress"},{"phrase":"slow process"},{"phrase":"slow down"}]', NULL, '/sləʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/slo/slow_/slow__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 29, 'regular', 'thường xuyên; đều đặn; thông thường', 'adjective', '[{"en":"Regular exercise helps you sleep better at night.","vi":"Tập thể dục đều đặn giúp bạn ngủ ngon hơn vào ban đêm."},{"en":"She has been a regular customer here for ten years.","vi":"Cô ấy là khách quen ở đây đã mười năm rồi."},{"en":"I''d like a regular coffee with milk, please.","vi":"Cho tôi một ly cà phê sữa cỡ thường."}]', '[{"phrase":"regular exercise"},{"phrase":"on a regular basis"},{"phrase":"regular customer"}]', NULL, '/ˈreɡjələr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regul/regular__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-04', 30, 'physical', 'thể chất; vật chất', 'adjective', '[{"en":"Physical activity is important for both your body and mind.","vi":"Hoạt động thể chất rất quan trọng cho cả cơ thể lẫn tinh thần."},{"en":"Farm work requires a lot of physical strength.","vi":"Công việc đồng áng đòi hỏi rất nhiều sức lực."},{"en":"I prefer physical books to reading on a screen.","vi":"Tôi thích sách giấy hơn là đọc trên màn hình."}]', '[{"phrase":"physical activity"},{"phrase":"physical exercise"},{"phrase":"physical health"},{"phrase":"physical strength"}]', NULL, '/ˈfɪzɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/phy/physi/physical__us_1.mp3', NULL, NULL);
